static int runtime_player_interact_item_frame(
        GmRuntime *r, const PsvPlayer *player, double block_distance) {
    GmRuntimeItemFrame *best = NULL;
    double sx, sy, sz, dx, dy, dz, best_distance = 3.0;
    if (!r || !player || !r->item_frames) return 0;
    gm_player_look_ray(
        &r->sin_table, player, &sx, &sy, &sz, &dx, &dy, &dz);
    sx += r->ox;
    sz += r->oz;
    for (int i = 0; i < r->item_frames_cap; ++i) {
        GmRuntimeItemFrame *frame = &r->item_frames[i];
        McAABB box;
        double distance;
        if (!frame->active || frame->dimension != r->dimension) continue;
        box = runtime_item_frame_box(frame);
        if (runtime_attack_ray_box_distance(
                sx, sy, sz, dx, dy, dz, &box, 3.0, &distance)
                && distance < best_distance
                && distance < block_distance) {
            best = frame;
            best_distance = distance;
        }
    }
    return best ? gm_runtime_item_frame_interact(
        r, best->eid, r->player.inv.current_item,
        r->tape_creative != 0) : 0;
}

