typedef struct {
    int width, height;
} RuntimePaintingArt;

static const RuntimePaintingArt runtime_painting_arts[26] = {
    {16,16}, {16,16}, {16,16}, {16,16}, {16,16}, {16,16}, {16,16},
    {32,16}, {32,16}, {32,16}, {32,16}, {32,16}, {16,32}, {16,32},
    {32,32}, {32,32}, {32,32}, {32,32}, {32,32}, {32,32}, {64,32},
    {64,64}, {64,64}, {64,64}, {64,48}, {64,48},
};

static McAABB runtime_item_frame_box(const GmRuntimeItemFrame *frame) {
    double half_x = frame->facing == 2 || frame->facing == 3
        ? 0.375 : 0.03125;
    double half_z = frame->facing == 4 || frame->facing == 5
        ? 0.375 : 0.03125;
    return mc_aabb_make(
        frame->x - half_x, frame->y - 0.375, frame->z - half_z,
        frame->x + half_x, frame->y + 0.375, frame->z + half_z);
}

int gm_runtime_item_frame_aabb(
        const GmRuntimeItemFrame *frame, McAABB *out) {
    if (!frame || !frame->active || !out) return 0;
    *out = runtime_item_frame_box(frame);
    return 1;
}

static void runtime_painting_geometry(
        int x, int y, int z, int facing, int art,
        double *px, double *py, double *pz, McAABB *box) {
    static const int dx[6] = {0, 0, 0, 0, -1, 1};
    static const int dz[6] = {0, 0, -1, 1, 0, 0};
    static const int ccw_x[6] = {0, 0, -1, 1, 0, 0};
    static const int ccw_z[6] = {0, 0, 0, 0, 1, -1};
    const int width = runtime_painting_arts[art].width;
    const int height = runtime_painting_arts[art].height;
    double cx = (double)x + 0.5 - (double)dx[facing] * 0.46875;
    double cy = (double)y + 0.5 + (height % 32 == 0 ? 0.5 : 0.0);
    double cz = (double)z + 0.5 - (double)dz[facing] * 0.46875;
    double side = width % 32 == 0 ? 0.5 : 0.0;
    double half_x = facing == 2 || facing == 3
        ? (double)width / 32.0 : 1.0 / 32.0;
    double half_z = facing == 4 || facing == 5
        ? (double)width / 32.0 : 1.0 / 32.0;
    cx += side * (double)ccw_x[facing];
    cz += side * (double)ccw_z[facing];
    if (px) *px = cx;
    if (py) *py = cy;
    if (pz) *pz = cz;
    if (box) *box = mc_aabb_make(
        cx - half_x, cy - (double)height / 32.0, cz - half_z,
        cx + half_x, cy + (double)height / 32.0, cz + half_z);
}

static McAABB runtime_painting_box(
        const GmRuntimePainting *painting) {
    McAABB box;
    runtime_painting_geometry(
        painting->hanging_x, painting->hanging_y, painting->hanging_z,
        painting->facing, painting->art,
        NULL, NULL, NULL, &box);
    return box;
}

int gm_runtime_painting_aabb(
        const GmRuntimePainting *painting, McAABB *out) {
    if (!painting || !painting->active || !out) return 0;
    *out = runtime_painting_box(painting);
    return 1;
}

static McAABB runtime_leash_knot_box(
        const GmRuntimeLeashKnot *knot) {
    return mc_aabb_make(
        knot->x - 0.1875, knot->y - 0.125, knot->z - 0.1875,
        knot->x + 0.1875, knot->y + 0.375, knot->z + 0.1875);
}

int gm_runtime_leash_knot_aabb(
        const GmRuntimeLeashKnot *knot, McAABB *out) {
    if (!knot || !knot->active || !out) return 0;
    *out = runtime_leash_knot_box(knot);
    return 1;
}

static int runtime_hanging_box_hits_block(
        const GmRuntime *r, const McAABB *box) {
    int x0 = mc_floor(box->minX);
    int y0 = mc_floor(box->minY);
    int z0 = mc_floor(box->minZ);
    int x1 = mc_floor(box->maxX - 1.0e-9);
    int y1 = mc_floor(box->maxY - 1.0e-9);
    int z1 = mc_floor(box->maxZ - 1.0e-9);
    for (int by = y0; by <= y1; ++by)
        for (int bz = z0; bz <= z1; ++bz)
            for (int bx = x0; bx <= x1; ++bx) {
                McAABB shapes[7];
                int id = gm_world_block(r->world, bx, by, bz);
                int meta = gm_world_meta(r->world, bx, by, bz);
                int count = runtime_static_collision_shapes(
                    r, bx, by, bz, id, meta, shapes);
                for (int shape = 0; shape < count; ++shape)
                    if (runtime_aabb_intersects(box, &shapes[shape]))
                        return 1;
            }
    return 0;
}

static int runtime_hanging_box_overlaps(
        const GmRuntime *r, const McAABB *box, int exclude_eid) {
    if (r->item_frames)
        for (int i = 0; i < r->item_frames_cap; ++i) {
            const GmRuntimeItemFrame *frame = &r->item_frames[i];
            McAABB other;
            if (!frame->active || frame->dimension != r->dimension
                    || frame->eid == exclude_eid)
                continue;
            other = runtime_item_frame_box(frame);
            if (runtime_aabb_intersects(box, &other)) return 1;
        }
    if (r->paintings)
        for (int i = 0; i < r->paintings_cap; ++i) {
            const GmRuntimePainting *painting = &r->paintings[i];
            McAABB other;
            if (!painting->active || painting->dimension != r->dimension
                    || painting->eid == exclude_eid)
                continue;
            runtime_painting_geometry(
                painting->hanging_x, painting->hanging_y,
                painting->hanging_z, painting->facing, painting->art,
                NULL, NULL, NULL, &other);
            if (runtime_aabb_intersects(box, &other)) return 1;
        }
    if (r->leash_knots)
        for (int i = 0; i < r->leash_knots_cap; ++i) {
            const GmRuntimeLeashKnot *knot = &r->leash_knots[i];
            McAABB other;
            if (!knot->active || knot->dimension != r->dimension
                    || knot->eid == exclude_eid)
                continue;
            other = runtime_leash_knot_box(knot);
            if (runtime_aabb_intersects(box, &other)) return 1;
        }
    return 0;
}

static int runtime_hanging_support_valid(
        const GmRuntime *r, int x, int y, int z, int facing) {
    static const int dx[6] = {0, 0, 0, 0, -1, 1};
    static const int dz[6] = {0, 0, -1, 1, 0, 0};
    int sx = x - dx[facing];
    int sz = z - dz[facing];
    int id = gm_world_block(r->world, sx, y, sz);
    int meta = gm_world_meta(r->world, sx, y, sz);
    return runtime_redstone_side_solid_1_11_2(
            r, sx, y, sz, facing)
        || gm_block_material_is_solid_1_11_2(id, meta)
        || id == 93 || id == 94 || id == 149 || id == 150;
}

static int runtime_painting_surface_valid(
        const GmRuntime *r, int x, int y, int z,
        int facing, int art, int exclude_eid) {
    static const int dx[6] = {0, 0, 0, 0, -1, 1};
    static const int dz[6] = {0, 0, -1, 1, 0, 0};
    static const int ccw_x[6] = {0, 0, -1, 1, 0, 0};
    static const int ccw_z[6] = {0, 0, 0, 0, 1, -1};
    McAABB box;
    int width, height, cols, rows, col0, row0;
    int support_x, support_z;
    if (!r || !r->world || facing < 2 || facing > 5
            || art < 0 || art >= 26 || y < 0 || y > 255)
        return 0;
    runtime_painting_geometry(
        x, y, z, facing, art, NULL, NULL, NULL, &box);
    if (runtime_hanging_box_hits_block(r, &box)
            || runtime_hanging_box_overlaps(r, &box, exclude_eid))
        return 0;
    width = runtime_painting_arts[art].width;
    height = runtime_painting_arts[art].height;
    cols = width / 16;
    rows = height / 16;
    if (cols < 1) cols = 1;
    if (rows < 1) rows = 1;
    col0 = (cols - 1) / -2;
    row0 = (rows - 1) / -2;
    support_x = x - dx[facing];
    support_z = z - dz[facing];
    for (int col = 0; col < cols; ++col)
        for (int row = 0; row < rows; ++row) {
            int sx = support_x + ccw_x[facing] * (col + col0);
            int sy = y + row + row0;
            int sz = support_z + ccw_z[facing] * (col + col0);
            if (!runtime_hanging_support_valid(
                    r, sx + dx[facing], sy, sz + dz[facing], facing))
                return 0;
        }
    return 1;
}

static int runtime_painting_grow(GmRuntime *r) {
    int old_cap = r->paintings_cap;
    int new_cap = old_cap > 0 ? old_cap * 2 : GM_RUNTIME_PAINTINGS_INITIAL;
    GmRuntimePainting *grown;
    if (new_cap > GM_RUNTIME_COLD_STORE_MAX)
        new_cap = GM_RUNTIME_COLD_STORE_MAX;
    if (new_cap <= old_cap) return 0;
    grown = (GmRuntimePainting *)realloc(
        r->paintings, (size_t)new_cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + old_cap, 0,
           (size_t)(new_cap - old_cap) * sizeof *grown);
    r->paintings = grown;
    r->paintings_cap = new_cap;
    return 1;
}

static int runtime_leash_knot_grow(GmRuntime *r) {
    int old_cap = r->leash_knots_cap;
    int new_cap = old_cap > 0
        ? old_cap * 2 : GM_RUNTIME_LEASH_KNOTS_INITIAL;
    GmRuntimeLeashKnot *grown;
    if (new_cap > GM_RUNTIME_COLD_STORE_MAX)
        new_cap = GM_RUNTIME_COLD_STORE_MAX;
    if (new_cap <= old_cap) return 0;
    grown = (GmRuntimeLeashKnot *)realloc(
        r->leash_knots, (size_t)new_cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + old_cap, 0,
           (size_t)(new_cap - old_cap) * sizeof *grown);
    r->leash_knots = grown;
    r->leash_knots_cap = new_cap;
    return 1;
}

int gm_runtime_painting_count(const GmRuntime *r) {
    return r ? r->painting_count : 0;
}

int gm_runtime_painting_get(
        const GmRuntime *r, int index, GmRuntimePainting *out) {
    int at = 0;
    if (!r || !out || index < 0) return 0;
    for (int i = 0; i < r->paintings_cap; ++i) {
        const GmRuntimePainting *painting = &r->paintings[i];
        if (!painting->active || painting->dimension != r->dimension)
            continue;
        if (at++ == index) {
            *out = *painting;
            return 1;
        }
    }
    return 0;
}

int gm_runtime_painting_set(
        GmRuntime *r, int dimension, int eid,
        int hanging_x, int hanging_y, int hanging_z,
        int facing, int art, int tick_counter) {
    int slot = -1, free_slot = -1, was_active = 0;
    if (!r || dimension != r->dimension || eid < 0
            || facing < 2 || facing > 5 || art < 0 || art >= 26
            || tick_counter < 0 || tick_counter > 100
            || !runtime_painting_surface_valid(
                r, hanging_x, hanging_y, hanging_z,
                facing, art, eid))
        return 0;
    for (int i = 0; i < r->paintings_cap; ++i) {
        GmRuntimePainting *candidate = &r->paintings[i];
        if (candidate->active && candidate->eid == eid) {
            slot = i;
            was_active = 1;
            break;
        }
        if (!candidate->active && free_slot < 0) free_slot = i;
    }
    if (slot < 0) slot = free_slot;
    if (slot < 0) {
        int old_cap = r->paintings_cap;
        if (!runtime_painting_grow(r)) return 0;
        slot = old_cap;
    }
    GmRuntimePainting *painting = &r->paintings[slot];
    memset(painting, 0, sizeof *painting);
    painting->active = 1;
    painting->dimension = dimension;
    painting->eid = eid;
    painting->hanging_x = hanging_x;
    painting->hanging_y = hanging_y;
    painting->hanging_z = hanging_z;
    painting->facing = facing;
    painting->art = art;
    painting->tick_counter = tick_counter;
    runtime_painting_geometry(
        hanging_x, hanging_y, hanging_z, facing, art,
        &painting->x, &painting->y, &painting->z, NULL);
    if (!was_active) ++r->painting_count;
    if (eid >= r->next_entity_id) r->next_entity_id = eid + 1;
    return 1;
}

int gm_runtime_leash_knot_count(const GmRuntime *r) {
    return r ? r->leash_knot_count : 0;
}

int gm_runtime_leash_knot_get(
        const GmRuntime *r, int index, GmRuntimeLeashKnot *out) {
    int at = 0;
    if (!r || !out || index < 0) return 0;
    for (int i = 0; i < r->leash_knots_cap; ++i) {
        const GmRuntimeLeashKnot *knot = &r->leash_knots[i];
        if (!knot->active || knot->dimension != r->dimension) continue;
        if (at++ == index) {
            *out = *knot;
            return 1;
        }
    }
    return 0;
}

int gm_runtime_leash_knot_set(
        GmRuntime *r, int dimension, int eid,
        int x, int y, int z, int tick_counter) {
    int slot = -1, free_slot = -1, was_active = 0;
    if (!r || dimension != r->dimension || eid < 0
            || y < 0 || y > 255 || tick_counter < 0 || tick_counter > 100
            || !runtime_is_fence_id(gm_world_block(r->world, x, y, z)))
        return 0;
    for (int i = 0; i < r->leash_knots_cap; ++i) {
        GmRuntimeLeashKnot *candidate = &r->leash_knots[i];
        if (candidate->active && candidate->eid == eid) {
            slot = i;
            was_active = 1;
            break;
        }
        if (candidate->active && candidate->dimension == dimension
                && candidate->hanging_x == x
                && candidate->hanging_y == y
                && candidate->hanging_z == z)
            return 0;
        if (!candidate->active && free_slot < 0) free_slot = i;
    }
    if (slot < 0) slot = free_slot;
    if (slot < 0) {
        int old_cap = r->leash_knots_cap;
        if (!runtime_leash_knot_grow(r)) return 0;
        slot = old_cap;
    }
    GmRuntimeLeashKnot *knot = &r->leash_knots[slot];
    memset(knot, 0, sizeof *knot);
    knot->active = 1;
    knot->dimension = dimension;
    knot->eid = eid;
    knot->x = (double)x + 0.5;
    knot->y = (double)y + 0.5;
    knot->z = (double)z + 0.5;
    knot->hanging_x = x;
    knot->hanging_y = y;
    knot->hanging_z = z;
    knot->tick_counter = tick_counter;
    if (!was_active) ++r->leash_knot_count;
    if (eid >= r->next_entity_id) r->next_entity_id = eid + 1;
    return 1;
}

static int runtime_hanging_drop_stack(
        GmRuntime *r, double x, double y, double z, ICStack stack) {
    JavaRandom entity_random;
    int64_t most, least;
    int eid;
    float hover, yaw;
    double motion_x, motion_z;
    if (!r || isr_is_empty(&stack) || r->next_entity_id <= 0
            || stack.tag_id < 0
            || (stack.tag_id > 0 && !gm_runtime_stack_tag(r, stack.tag_id))
            || r->loaded_entity_order_count >= GM_RUNTIME_COLD_STORE_MAX)
        return 0;
    hover = (float)(runtime_math_random_next_double(r) * (MC_PI * 2.0));
    yaw = (float)(runtime_math_random_next_double(r) * 360.0);
    motion_x = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    motion_z = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    eid = r->next_entity_id++;
    jrand_set(&entity_random, runtime_java_random_seed_next_long(
        &r->entity_seed_generator_seed48));
    runtime_next_server_uuid(r, &most, &least);
    if (!gm_live_spawn_stack_exact_hover(
            &r->entities, eid, x, y, z,
            motion_x, 0.20000000298023224, motion_z, yaw, hover,
            stack, 0, 10, 0)) {
        --r->next_entity_id;
        return 0;
    }
    if (!gm_live_set_item_environment_state(
            &r->entities, eid, entity_random.seed, -1, 0, 0)
            || !gm_runtime_set_item_entity_uuid(r, eid, most, least)
            || !runtime_loaded_entity_order_append(r, eid))
        return 0;
    return 1;
}

static int runtime_hanging_drop_item(
        GmRuntime *r, double x, double y, double z, int item) {
    return runtime_hanging_drop_stack(r, x, y, z, ic_mk(item, 1, 0));
}

/* Entity.entityDropItem: exact constructor position and the default ten-tick
 * pickup delay, without InventoryHelper's split/offset/motion overwrite. */
static int runtime_entity_drop_stack(
        GmRuntime *r, double x, double y, double z, ICStack stack) {
    JavaRandom entity_random;
    int64_t most, least;
    int eid;
    float hover, yaw;
    double motion_x, motion_z;
    if (!r || isr_is_empty(&stack)) return 0;
    hover = (float)(runtime_math_random_next_double(r) * (MC_PI * 2.0));
    yaw = (float)(runtime_math_random_next_double(r) * 360.0);
    motion_x = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    motion_z = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    eid = r->next_entity_id++;
    jrand_set(&entity_random, runtime_java_random_seed_next_long(
        &r->entity_seed_generator_seed48));
    runtime_next_server_uuid(r, &most, &least);
    return gm_live_spawn_stack_exact_hover(
               &r->entities, eid, x, y, z,
               motion_x, 0.20000000298023224, motion_z, yaw, hover,
               stack, 0, 10, 0)
        && gm_live_set_item_environment_state(
               &r->entities, eid, entity_random.seed, -1, 0, 1)
        && gm_runtime_set_item_entity_uuid(r, eid, most, least)
        && runtime_loaded_entity_order_append(r, eid);
}

int gm_runtime_living_leash_interact(
        GmRuntime *r, int eid, int hand_slot) {
    const EwStore *store;
    GmLivingLeashState leash;
    ICStack held;
    int slot;
    if (!r || !isr_slot_ok(hand_slot)
            || !gm_mobs_get_living_leash_state(&r->mobs, eid, &leash))
        return 0;
    slot = gm_mobs_find_slot_by_eid(&r->mobs, eid);
    store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
    if (slot <= 0 || !store->alive[slot]) return 0;
    if (leash.leashed && leash.holder_kind == 1
            && leash.holder_eid == r->player_entity_id) {
        (void)gm_mobs_living_clear_leash(&r->mobs, eid);
        if (!r->tape_creative)
            (void)runtime_hanging_drop_item(
                r, store->x[slot], store->y[slot], store->z[slot], 420);
        return 1;
    }
    held = isr_get_stack(&r->player.inv, hand_slot);
    if (leash.leashed || held.item != 420 || held.count <= 0)
        return 0;
    if (!gm_mobs_living_can_be_leashed(&r->mobs, eid)) return 0;
    if (!gm_mobs_living_set_leash_player(
            &r->mobs, eid, r->player_entity_id))
        return 0;
    /* EntityLiving shrinks a lead even for a creative player. */
    (void)isr_decr_stack_size(&r->player.inv, hand_slot, 1);
    return 1;
}

static GmRuntimePainting *runtime_painting_by_eid(
        GmRuntime *r, int eid) {
    if (!r || eid < 0) return NULL;
    for (int i = 0; i < r->paintings_cap; ++i)
        if (r->paintings[i].active && r->paintings[i].eid == eid)
            return &r->paintings[i];
    return NULL;
}

static GmRuntimeLeashKnot *runtime_leash_knot_by_eid(
        GmRuntime *r, int eid) {
    if (!r || eid < 0) return NULL;
    for (int i = 0; i < r->leash_knots_cap; ++i)
        if (r->leash_knots[i].active && r->leash_knots[i].eid == eid)
            return &r->leash_knots[i];
    return NULL;
}

int gm_runtime_painting_set_uuid(
        GmRuntime *r, int eid, int64_t most, int64_t least) {
    GmRuntimePainting *painting = runtime_painting_by_eid(r, eid);
    if (!painting) return 0;
    painting->uuid_present = 1;
    painting->uuid_most = most;
    painting->uuid_least = least;
    return 1;
}

int gm_runtime_leash_knot_set_uuid(
        GmRuntime *r, int eid, int64_t most, int64_t least) {
    GmRuntimeLeashKnot *knot = runtime_leash_knot_by_eid(r, eid);
    if (!knot) return 0;
    knot->uuid_present = 1;
    knot->uuid_most = most;
    knot->uuid_least = least;
    return 1;
}

int gm_runtime_break_painting(
        GmRuntime *r, int eid, int creative) {
    static const int dx[6] = {0, 0, 0, 0, -1, 1};
    static const int dz[6] = {0, 0, -1, 1, 0, 0};
    GmRuntimePainting *painting = runtime_painting_by_eid(r, eid);
    if (!painting || painting->dimension != r->dimension
            || (creative != 0 && creative != 1))
        return 0;
    if (r->do_entity_drops) {
        runtime_sound_event_append(
            r, GM_SOUND_PAINTING_BREAK, GM_SOUND_CATEGORY_NEUTRAL,
            painting->eid, 0, painting->x, painting->y, painting->z,
            1.0F, 1.0F);
        if (!creative)
            (void)runtime_hanging_drop_item(
                r,
                painting->x + (double)((float)dx[painting->facing] * 0.15F),
                painting->y,
                painting->z + (double)((float)dz[painting->facing] * 0.15F),
                321);
    }
    runtime_loaded_entity_order_remove(r, painting->eid);
    memset(painting, 0, sizeof *painting);
    --r->painting_count;
    return 1;
}

int gm_runtime_place_painting(
        GmRuntime *r, int hanging_x, int hanging_y, int hanging_z,
        int facing, int hand_slot, int creative) {
    JavaRandom entity_random;
    ICStack held;
    int valid[26], valid_count = 0, art, eid;
    int64_t most, least;
    if (!r || !r->world || facing < 2 || facing > 5
            || !isr_slot_ok(hand_slot)
            || (creative != 0 && creative != 1))
        return 0;
    held = isr_get_stack(&r->player.inv, hand_slot);
    if (held.item != 321 || held.count <= 0) return 0;
    for (art = 0; art < 26; ++art)
        if (runtime_painting_surface_valid(
                r, hanging_x, hanging_y, hanging_z,
                facing, art, -1))
            valid[valid_count++] = art;
    if (valid_count == 0) return 0;
    eid = r->next_entity_id;
    jrand_set(&entity_random, runtime_java_random_seed_next_long(
        &r->entity_seed_generator_seed48));
    art = valid[jrand_int_bound(&entity_random, valid_count)];
    if (!gm_runtime_painting_set(
            r, r->dimension, eid,
            hanging_x, hanging_y, hanging_z, facing, art, 0))
        return 0;
    GmRuntimePainting *painting = runtime_painting_by_eid(r, eid);
    runtime_next_server_uuid(r, &most, &least);
    painting->uuid_present = 1;
    painting->uuid_most = most;
    painting->uuid_least = least;
    if (!runtime_loaded_entity_order_append(r, eid)) {
        memset(painting, 0, sizeof *painting);
        --r->painting_count;
        return 0;
    }
    if (!creative)
        (void)isr_decr_stack_size(&r->player.inv, hand_slot, 1);
    runtime_sound_event_append(
        r, GM_SOUND_PAINTING_PLACE, GM_SOUND_CATEGORY_NEUTRAL,
        painting->eid, 0, painting->x, painting->y, painting->z,
        1.0F, 1.0F);
    return 1;
}

static int runtime_living_in_leash_box(
        const GmMobLive *m, int eid, const McAABB *query) {
    McAABB entity;
    return gm_mobs_entity_aabb(m, eid, &entity)
        && mc_aabb_intersects(&entity, query);
}

static int runtime_transfer_player_living_to_knot(
        GmRuntime *r, GmRuntimeLeashKnot *knot,
        const McAABB *query) {
    int changed = 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(&r->mobs, &cursor)) > 0) {
        const EwStore *store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
        if (!store->alive[slot]
                || !gm_mobs_vanilla_leashable_type(store->type[slot])
                || r->mobs.entity_dimension[slot] != r->dimension
                || !r->mobs.llama_leashed[slot]
                || r->mobs.llama_leash_holder_kind[slot] != 1
                || !runtime_living_in_leash_box(
                    &r->mobs, store->id[slot], query))
            continue;
        changed += gm_mobs_living_set_leash_knot(
            &r->mobs, store->id[slot], knot->eid,
            knot->x, knot->y, knot->z);
    }
    gm_mobs_living_cold_flush(&r->mobs);
    return changed;
}

int gm_runtime_attach_living_to_fence(
        GmRuntime *r, int x, int y, int z) {
    const EwStore *store;
    GmRuntimeLeashKnot *knot = NULL;
    McAABB query = mc_aabb_make(
        (double)x - 7.0, (double)y - 7.0, (double)z - 7.0,
        (double)x + 7.0, (double)y + 7.0, (double)z + 7.0);
    int eligible = 0;
    if (!r || !r->world
            || !runtime_is_fence_id(gm_world_block(r->world, x, y, z)))
        return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(&r->mobs, &cursor)) > 0) {
        store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
        if (store->alive[slot]
                && gm_mobs_vanilla_leashable_type(store->type[slot])
                && r->mobs.entity_dimension[slot] == r->dimension
                && r->mobs.llama_leashed[slot]
                && r->mobs.llama_leash_holder_kind[slot] == 1
                && runtime_living_in_leash_box(
                    &r->mobs, store->id[slot], &query))
            ++eligible;
    }
    gm_mobs_living_cold_flush(&r->mobs);
    if (!eligible) return 0;
    for (int i = 0; i < r->leash_knots_cap; ++i) {
        GmRuntimeLeashKnot *candidate = &r->leash_knots[i];
        if (candidate->active && candidate->dimension == r->dimension
                && candidate->hanging_x == x
                && candidate->hanging_y == y
                && candidate->hanging_z == z) {
            knot = candidate;
            break;
        }
    }
    if (!knot) {
        JavaRandom entity_random;
        int64_t most, least;
        int eid = r->next_entity_id;
        jrand_set(&entity_random, runtime_java_random_seed_next_long(
            &r->entity_seed_generator_seed48));
        (void)entity_random;
        if (!gm_runtime_leash_knot_set(
                r, r->dimension, eid, x, y, z, 0))
            return 0;
        knot = runtime_leash_knot_by_eid(r, eid);
        runtime_next_server_uuid(r, &most, &least);
        knot->uuid_present = 1;
        knot->uuid_most = most;
        knot->uuid_least = least;
        if (!runtime_loaded_entity_order_append(r, eid)) {
            memset(knot, 0, sizeof *knot);
            --r->leash_knot_count;
            return 0;
        }
        runtime_sound_event_append(
            r, GM_SOUND_LEASH_KNOT_PLACE, GM_SOUND_CATEGORY_NEUTRAL,
            knot->eid, 0, knot->x, knot->y, knot->z, 1.0F, 1.0F);
    }
    return runtime_transfer_player_living_to_knot(r, knot, &query);
}

int gm_runtime_attach_llamas_to_fence(
        GmRuntime *r, int x, int y, int z) {
    return gm_runtime_attach_living_to_fence(r, x, y, z);
}

static void runtime_break_leash_knot(
        GmRuntime *r, GmRuntimeLeashKnot *knot, int creative) {
    int eid;
    if (!r || !knot || !knot->active) return;
    eid = knot->eid;
    runtime_sound_event_append(
        r, GM_SOUND_LEASH_KNOT_BREAK, GM_SOUND_CATEGORY_NEUTRAL,
        knot->eid, 0, knot->x, knot->y, knot->z, 1.0F, 1.0F);
    runtime_loaded_entity_order_remove(r, eid);
    memset(knot, 0, sizeof *knot);
    --r->leash_knot_count;
    (void)gm_mobs_living_invalidate_leash_knot(
        &r->mobs, eid, creative);
}

int gm_runtime_leash_knot_interact(
        GmRuntime *r, int eid, int creative) {
    GmRuntimeLeashKnot *knot = runtime_leash_knot_by_eid(r, eid);
    if (!knot || knot->dimension != r->dimension
            || (creative != 0 && creative != 1))
        return 0;
    McAABB query = mc_aabb_make(
        knot->x - 7.0, knot->y - 7.0, knot->z - 7.0,
        knot->x + 7.0, knot->y + 7.0, knot->z + 7.0);
    if (runtime_transfer_player_living_to_knot(r, knot, &query) == 0)
        runtime_break_leash_knot(r, knot, creative);
    return 1;
}

int gm_runtime_damage_leash_knot(
        GmRuntime *r, int eid, int creative) {
    GmRuntimeLeashKnot *knot = runtime_leash_knot_by_eid(r, eid);
    if (!knot || knot->dimension != r->dimension
            || (creative != 0 && creative != 1))
        return 0;
    runtime_break_leash_knot(r, knot, creative);
    return 1;
}

int gm_runtime_restore_living_leash_knot(
        GmRuntime *r, int living_eid, int knot_eid) {
    GmRuntimeLeashKnot *knot = runtime_leash_knot_by_eid(r, knot_eid);
    if (!r || !knot || knot->dimension != r->dimension)
        return 0;
    return gm_mobs_living_set_leash_knot(
        &r->mobs, living_eid, knot_eid, knot->x, knot->y, knot->z);
}

int gm_runtime_restore_llama_leash_knot(
        GmRuntime *r, int llama_eid, int knot_eid) {
    return gm_runtime_restore_living_leash_knot(r, llama_eid, knot_eid);
}

int gm_runtime_restore_living_leash_pending(
        GmRuntime *r, int living_eid, int x, int y, int z) {
    int slot;
    if (!r || living_eid < 0
            || r->leash_knot_pending_count >= EW_MAX_ENTITIES)
        return 0;
    slot = gm_mobs_find_slot_by_eid(&r->mobs, living_eid);
    if (slot <= 0 || r->mobs.llama_leash_pending[slot]
            || !gm_mobs_living_set_leash_pending(
                &r->mobs, living_eid, x, y, z))
        return 0;
    ++r->leash_knot_pending_count;
    return 1;
}

int gm_runtime_restore_llama_leash_pending(
        GmRuntime *r, int llama_eid, int x, int y, int z) {
    return gm_runtime_restore_living_leash_pending(
        r, llama_eid, x, y, z);
}

/* EntityLiving recreates a fence leash from its pending NBT during that
 * llama's first update. Run this after the existing hanging-entity pass so a
 * newly constructed knot is appended to loadedEntityList but is not itself
 * advanced until the next world tick. */
static void runtime_restore_pending_living_knots(GmRuntime *r) {
    const EwStore *store;
    if (!r || r->leash_knot_pending_count <= 0) return;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(&r->mobs, &cursor)) > 0) {
        GmRuntimeLeashKnot *knot = NULL;
        int x, y, z;
        store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
        if (!store->alive[slot]
                || !gm_mobs_vanilla_leashable_type(store->type[slot])
                || !r->mobs.llama_leash_pending[slot])
            continue;
        x = r->mobs.llama_leash_pending_x[slot];
        y = r->mobs.llama_leash_pending_y[slot];
        z = r->mobs.llama_leash_pending_z[slot];
        for (int index = 0; index < r->leash_knots_cap; ++index) {
            GmRuntimeLeashKnot *candidate = &r->leash_knots[index];
            if (candidate->active && candidate->dimension == r->dimension
                    && candidate->hanging_x == x
                    && candidate->hanging_y == y
                    && candidate->hanging_z == z) {
                knot = candidate;
                break;
            }
        }
        if (!knot) {
            JavaRandom entity_random;
            int64_t most, least;
            int eid = r->next_entity_id;
            jrand_set(&entity_random, runtime_java_random_seed_next_long(
                &r->entity_seed_generator_seed48));
            (void)entity_random;
            if (!gm_runtime_leash_knot_set(
                    r, r->dimension, eid, x, y, z, 0))
                continue;
            knot = runtime_leash_knot_by_eid(r, eid);
            /* World.updateEntities' index loop observes the knot appended by
             * EntityLiving.recreateLeash later in the same pass. */
            knot->tick_counter = 1;
            runtime_next_server_uuid(r, &most, &least);
            knot->uuid_present = 1;
            knot->uuid_most = most;
            knot->uuid_least = least;
            if (!runtime_loaded_entity_order_append(r, eid)) {
                memset(knot, 0, sizeof *knot);
                --r->leash_knot_count;
                continue;
            }
            runtime_sound_event_append(
                r, GM_SOUND_LEASH_KNOT_PLACE, GM_SOUND_CATEGORY_NEUTRAL,
                knot->eid, 0, knot->x, knot->y, knot->z, 1.0F, 1.0F);
        }
        if (gm_mobs_living_set_leash_knot(
                &r->mobs, store->id[slot], knot->eid,
                knot->x, knot->y, knot->z))
        --r->leash_knot_pending_count;
    }
    gm_mobs_living_cold_flush(&r->mobs);
}

static int runtime_player_interact_leash_knot(
        GmRuntime *r, const PsvPlayer *player, double block_distance) {
    GmRuntimeLeashKnot *best = NULL;
    double sx, sy, sz, dx, dy, dz, best_distance = 3.0;
    if (!r || !player || r->leash_knot_count <= 0) return 0;
    gm_player_look_ray(
        &r->sin_table, player, &sx, &sy, &sz, &dx, &dy, &dz);
    sx += r->ox;
    sz += r->oz;
    for (int i = 0; i < r->leash_knots_cap; ++i) {
        GmRuntimeLeashKnot *knot = &r->leash_knots[i];
        McAABB box;
        double distance;
        if (!knot->active || knot->dimension != r->dimension) continue;
        box = runtime_leash_knot_box(knot);
        if (runtime_attack_ray_box_distance(
                sx, sy, sz, dx, dy, dz, &box, 3.0, &distance)
                && distance < best_distance
                && distance < block_distance) {
            best = knot;
            best_distance = distance;
        }
    }
    return best ? gm_runtime_leash_knot_interact(
        r, best->eid, r->tape_creative != 0) : 0;
}

static int runtime_player_attack_painting(GmRuntime *r) {
    GmRuntimePainting *best = NULL;
    double sx, sy, sz, dx, dy, dz, best_distance = PSV_REACH;
    if (!r || r->painting_count <= 0) return 0;
    gm_player_look_ray(
        &r->sin_table, &r->player, &sx, &sy, &sz, &dx, &dy, &dz);
    sx += r->ox;
    sz += r->oz;
    for (int i = 0; i < r->paintings_cap; ++i) {
        GmRuntimePainting *painting = &r->paintings[i];
        McAABB box;
        double distance;
        if (!painting->active || painting->dimension != r->dimension)
            continue;
        box = runtime_painting_box(painting);
        if (runtime_attack_ray_box_distance(
                sx, sy, sz, dx, dy, dz, &box,
                PSV_REACH, &distance) && distance < best_distance) {
            best = painting;
            best_distance = distance;
        }
    }
    return best ? gm_runtime_break_painting(
        r, best->eid, r->tape_creative != 0) : 0;
}

static int runtime_player_attack_leash_knot(GmRuntime *r) {
    GmRuntimeLeashKnot *best = NULL;
    double sx, sy, sz, dx, dy, dz, best_distance = PSV_REACH;
    if (!r || r->leash_knot_count <= 0) return 0;
    gm_player_look_ray(
        &r->sin_table, &r->player, &sx, &sy, &sz, &dx, &dy, &dz);
    sx += r->ox;
    sz += r->oz;
    for (int i = 0; i < r->leash_knots_cap; ++i) {
        GmRuntimeLeashKnot *knot = &r->leash_knots[i];
        McAABB box;
        double distance;
        if (!knot->active || knot->dimension != r->dimension) continue;
        box = runtime_leash_knot_box(knot);
        if (runtime_attack_ray_box_distance(
                sx, sy, sz, dx, dy, dz, &box,
                PSV_REACH, &distance) && distance < best_distance) {
            best = knot;
            best_distance = distance;
        }
    }
    if (!best) return 0;
    runtime_break_leash_knot(r, best, 0);
    return 1;
}

static int runtime_tick_hanging_entity_eid(GmRuntime *r, int eid) {
    GmRuntimeItemFrame *frame = runtime_item_frame_by_eid(r, eid);
    if (frame && frame->dimension == r->dimension) {
        if (frame->tick_counter++ == 100) {
            frame->tick_counter = 0;
            if (!runtime_item_frame_surface_valid_for(
                    r, frame->hanging_x, frame->hanging_y,
                    frame->hanging_z, frame->facing, frame->eid))
                (void)gm_runtime_damage_item_frame(r, eid, 0, 1);
        }
        return 1;
    }
    GmRuntimePainting *painting = runtime_painting_by_eid(r, eid);
    if (painting && painting->dimension == r->dimension) {
        if (painting->tick_counter++ == 100) {
            painting->tick_counter = 0;
            if (!runtime_painting_surface_valid(
                    r, painting->hanging_x, painting->hanging_y,
                    painting->hanging_z, painting->facing,
                    painting->art, painting->eid))
                (void)gm_runtime_break_painting(r, eid, 0);
        }
        return 1;
    }
    GmRuntimeLeashKnot *knot = runtime_leash_knot_by_eid(r, eid);
    if (knot && knot->dimension == r->dimension) {
        if (knot->tick_counter++ == 100) {
            knot->tick_counter = 0;
            if (!runtime_is_fence_id(gm_world_block(
                    r->world, knot->hanging_x,
                    knot->hanging_y, knot->hanging_z)))
                runtime_break_leash_knot(r, knot, 0);
        }
        return 1;
    }
    return 0;
}

void gm_runtime_tick_hanging_entities(GmRuntime *r) {
    int order = 0;
    if (!r || !r->world) return;
    /* World.updateEntities traverses one loadedEntityList. Preserve that
     * order across the three cold hanging stores; removal compacts the list,
     * so stay on the same index when the current callback retires itself. */
    while (order < r->loaded_entity_order_count) {
        int eid = r->loaded_entity_order[order];
        if (!runtime_tick_hanging_entity_eid(r, eid)
                || (order < r->loaded_entity_order_count
                    && r->loaded_entity_order[order] == eid))
            ++order;
    }
    /* Direct legacy fixtures can own a hanging entity without a restored
     * loaded-list row. Tick those once after every represented ordered row. */
    if (r->item_frames)
        for (int i = 0; i < r->item_frames_cap; ++i)
            if (r->item_frames[i].active
                    && runtime_loaded_entity_order_key(
                        r, r->item_frames[i].eid)
                        >= GM_RUNTIME_COLD_STORE_MAX)
                (void)runtime_tick_hanging_entity_eid(
                    r, r->item_frames[i].eid);
    if (r->paintings)
        for (int i = 0; i < r->paintings_cap; ++i)
            if (r->paintings[i].active
                    && runtime_loaded_entity_order_key(
                        r, r->paintings[i].eid)
                        >= GM_RUNTIME_COLD_STORE_MAX)
                (void)runtime_tick_hanging_entity_eid(
                    r, r->paintings[i].eid);
    if (r->leash_knots)
        for (int i = 0; i < r->leash_knots_cap; ++i)
            if (r->leash_knots[i].active
                    && runtime_loaded_entity_order_key(
                        r, r->leash_knots[i].eid)
                        >= GM_RUNTIME_COLD_STORE_MAX)
                (void)runtime_tick_hanging_entity_eid(
                    r, r->leash_knots[i].eid);
}

