static int runtime_generated_chest_info(
        const GmRuntime *r, int x, int y, int z,
        int *table_id, long long *loot_seed) {
    int tid = -1;
    long long seed = 0;
    if (!r || r->dimension != 0) return 0;
    if (gm_stronghold_chest_info(r->seed, x, y, z, &tid, &seed)) {
        if (table_id) *table_id = tid;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    if (popmc_dungeon_chest_info(r->seed, x, y, z, &seed, NULL)) {
        if (table_id) *table_id = CHEST_LOOT_SIMPLE_DUNGEON;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    if (popmc_desert_chest_info(r->seed, x, y, z, &seed, NULL)) {
        if (table_id) *table_id = CHEST_LOOT_DESERT_PYRAMID;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    if (popmc_jungle_chest_info(r->seed, x, y, z, &seed, NULL)) {
        if (table_id) *table_id = CHEST_LOOT_JUNGLE_TEMPLE;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    if (popmc_village_chest_info(r->seed, x, y, z, &seed, NULL)) {
        if (table_id) *table_id = CHEST_LOOT_VILLAGE_BLACKSMITH;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    if (popmc_igloo_chest_info(r->seed, x, y, z, &seed, NULL)) {
        if (table_id) *table_id = CHEST_LOOT_IGLOO;
        if (loot_seed) *loot_seed = seed;
        return 1;
    }
    return 0;
}

/* Minecraft 1.11.2 MathHelper.atan2 uses a 257-entry arcsine table and one
 * inverse-square-root Newton step. Projectile rotation exposes the resulting
 * float approximation, so libc atan2 is observably different. */
static double runtime_java_math_atan2(double y, double x)
{
    static double asine[257];
    static double cosine[257];
    static int initialized;
    const double frac_bias = 17592186044416.0;
    double squared = x * x + y * y;
    double half;
    double inv;
    double biased;
    double table_value;
    double table_cosine;
    double quantized;
    double error;
    double correction;
    uint64_t bits;
    int negative_y;
    int negative_x;
    int swapped;
    int index;

    if (isnan(squared)) return NAN;
    if (!initialized) {
        for (int i = 0; i <= 256; ++i) {
            double value = asin((double)i / 256.0);
            asine[i] = value;
            cosine[i] = cos(value);
        }
        initialized = 1;
    }
    negative_y = y < 0.0;
    if (negative_y) y = -y;
    negative_x = x < 0.0;
    if (negative_x) x = -x;
    swapped = y > x;
    if (swapped) {
        double hold = x;
        x = y;
        y = hold;
    }
    half = 0.5 * squared;
    memcpy(&bits, &squared, sizeof bits);
    bits = UINT64_C(6910469410427058090) - (bits >> 1);
    memcpy(&inv, &bits, sizeof inv);
    inv = inv * (1.5 - half * inv * inv);
    x *= inv;
    y *= inv;
    biased = frac_bias + y;
    memcpy(&bits, &biased, sizeof bits);
    index = (int)(uint32_t)bits;
    table_value = asine[index];
    table_cosine = cosine[index];
    quantized = biased - frac_bias;
    error = y * table_cosine - x * quantized;
    correction = (6.0 + error * error) * error
        * 0.16666666666666666;
    table_value += correction;
    if (swapped) table_value = MC_PI / 2.0 - table_value;
    if (negative_x) table_value = MC_PI - table_value;
    if (negative_y) table_value = -table_value;
    return table_value;
}

double gm_runtime_mathhelper_atan2(double y, double x)
{
    return runtime_java_math_atan2(y, x);
}

static long long runtime_loaded_entity_order_key(
        const GmRuntime *r, int eid)
{
    if (!r || eid < 0) return LLONG_MAX;
    for (int index = 0; index < r->loaded_entity_order_count; ++index)
        if (r->loaded_entity_order[index] == eid)
            return index;
    /* Spawned entities append to World.loadedEntityList. Until every spawn
     * site records that append explicitly, retain the old deterministic EID
     * fallback after every restored row. */
    return (long long)GM_RUNTIME_COLD_STORE_MAX + (unsigned int)eid;
}

static void runtime_loaded_entity_order_remove(GmRuntime *r, int eid)
{
    if (!r || eid < 0) return;
    for (int index = 0; index < r->loaded_entity_order_count; ++index) {
        if (r->loaded_entity_order[index] != eid) continue;
        memmove(&r->loaded_entity_order[index],
                &r->loaded_entity_order[index + 1],
                (size_t)(r->loaded_entity_order_count - index - 1)
                    * sizeof r->loaded_entity_order[0]);
        --r->loaded_entity_order_count;
        return;
    }
}

static int runtime_loaded_entity_order_reserve(GmRuntime *r, int need) {
    int *grown;
    int cap;
    if (!r || need < 0 || need > GM_RUNTIME_COLD_STORE_MAX) return 0;
    if (need <= r->loaded_entity_order_cap) return 1;
    cap = r->loaded_entity_order_cap > 0
        ? r->loaded_entity_order_cap : GM_RUNTIME_LOADED_ENTITY_ORDER;
    while (cap < need) {
        if (cap > GM_RUNTIME_COLD_STORE_MAX / 2) {
            cap = GM_RUNTIME_COLD_STORE_MAX;
            break;
        }
        cap *= 2;
    }
    if (cap < need) return 0;
    grown = (int *)realloc(
        r->loaded_entity_order, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    r->loaded_entity_order = grown;
    r->loaded_entity_order_cap = cap;
    return 1;
}

static int runtime_cold_reserve(
        void **storage, int *capacity, int need, int initial,
        size_t element_size) {
    void *grown;
    int cap;
    if (!storage || !capacity || need < 0
            || need > GM_RUNTIME_COLD_STORE_MAX || element_size == 0)
        return 0;
    if (need <= *capacity) return 1;
    cap = *capacity > 0 ? *capacity : initial;
    if (cap < 1) cap = 1;
    while (cap < need) {
        if (cap > GM_RUNTIME_COLD_STORE_MAX / 2) {
            cap = GM_RUNTIME_COLD_STORE_MAX;
            break;
        }
        cap *= 2;
    }
    if (cap < need || element_size > SIZE_MAX / (size_t)cap) return 0;
    grown = realloc(*storage, (size_t)cap * element_size);
    if (!grown) return 0;
    memset((unsigned char *)grown + (size_t)*capacity * element_size, 0,
           (size_t)(cap - *capacity) * element_size);
    *storage = grown;
    *capacity = cap;
    return 1;
}

#define RUNTIME_COLD_RESERVE(runtime, field, need, initial) \
    runtime_cold_reserve((void **)&(runtime)->field, \
        &(runtime)->field##_cap, (need), (initial), \
        sizeof *(runtime)->field)

static int runtime_loaded_entity_order_append(GmRuntime *r, int eid)
{
    if (!r || eid < 0) return 0;
    for (int index = 0; index < r->loaded_entity_order_count; ++index)
        if (r->loaded_entity_order[index] == eid)
            return 1;
    if (!runtime_loaded_entity_order_reserve(
            r, r->loaded_entity_order_count + 1))
        return 0;
    r->loaded_entity_order[r->loaded_entity_order_count++] = eid;
    return 1;
}

static void runtime_capture_mob_slots(
        const GmRuntime *r, int eids[EW_MAX_ENTITIES])
{
    const EwStore *store;
    memset(eids, 0, sizeof(int) * EW_MAX_ENTITIES);
    if (!r || r->loaded_entity_order_count == 0) return;
    store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
    for (int slot = 1; slot < EW_MAX_ENTITIES; ++slot)
        if (store->alive[slot]
                && r->mobs.entity_dimension[slot] == r->dimension)
            eids[slot] = store->id[slot];
}

static void runtime_reconcile_removed_mob_order(
        GmRuntime *r, const int eids[EW_MAX_ENTITIES])
{
    const EwStore *store;
    if (!r || r->loaded_entity_order_count == 0) return;
    store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
    for (int slot = 1; slot < EW_MAX_ENTITIES; ++slot)
        if (eids[slot] > 0
                && (!store->alive[slot] || store->id[slot] != eids[slot]))
            runtime_loaded_entity_order_remove(r, eids[slot]);
    /* Cold living slots are append-only, so an inactive record retains the
     * exact EID that disappeared during this tick. */
    for (int cold = 0; cold < r->mobs.living_cold_count; ++cold) {
        const GmLivingColdSlot *entity =
            gm_mobs_living_cold_ref(&r->mobs, cold);
        if (entity && !entity->store_alive && entity->store_id > 0)
            runtime_loaded_entity_order_remove(r, entity->store_id);
    }
}

