static int runtime_live_item_eid_active(const GmRuntime *r, int eid)
{
    if (!r || eid < 0) return 0;
    for (int index = 0;
            index < gm_live_entity_slot_count(&r->entities); ++index) {
        const GmLiveEnt *entity =
            gm_live_entity_ref(&r->entities, index);
        if (!entity) continue;
        if (entity->active && entity->type == 0 && entity->eid == eid)
            return 1;
    }
    return 0;
}

/* The runtime keeps hot entity families in separate arrays, but Java ticks
 * one loadedEntityList. If all current carts precede all current living mobs,
 * run the cart family first so a spawner-cart append is included in the mob
 * pass later in the same tick. The inverse ordering keeps the existing late
 * cart pass. Mixed cart/mob interleaving remains deliberately fail-closed at
 * capsule capability boundaries rather than being guessed here. */
static int runtime_all_minecarts_precede_mobs(const GmRuntime *r)
{
    GmMobLive *mobs;
    const EwStore *store;
    long long last_cart_order = LLONG_MIN;
    long long first_mob_order = LLONG_MAX;
    int found_cart = 0, found_mob = 0;
    if (!r || r->minecart_count <= 0) return 0;
    for (int i = 0; i < r->minecarts_cap; ++i) {
        const GmRuntimeMinecart *cart = &r->minecarts[i];
        long long order;
        if (!cart->active || cart->dimension != r->dimension) continue;
        order = runtime_loaded_entity_order_key(r, cart->eid);
        if (order == LLONG_MAX) return 0;
        if (order > last_cart_order) last_cart_order = order;
        found_cart = 1;
    }
    mobs = (GmMobLive *)&r->mobs;
    int cursor = 0;
    int slot;
    while ((slot = gm_mobs_living_next_slot(mobs, &cursor)) > 0) {
        long long order;
        store = r->mobs.current ? &r->mobs.b : &r->mobs.a;
        if (!store->alive[slot]
                || r->mobs.entity_dimension[slot] != r->dimension)
            continue;
        order = runtime_loaded_entity_order_key(r, store->id[slot]);
        if (order < first_mob_order) first_mob_order = order;
        found_mob = 1;
    }
    gm_mobs_living_cold_flush(mobs);
    return found_cart && (!found_mob || last_cart_order < first_mob_order);
}

static GmMobExplosionTarget *runtime_living_targets(
        const GmRuntime *r, GmMobExplosionTarget *inline_targets,
        int *count) {
    int capacity;
    GmMobExplosionTarget *targets = inline_targets;
    if (!r || !inline_targets || !count) return NULL;
    capacity = gm_mobs_living_count(&r->mobs);
    if (capacity < GM_MOB_CAPACITY) capacity = GM_MOB_CAPACITY;
    if (capacity > GM_MOB_CAPACITY) {
        targets = (GmMobExplosionTarget *)malloc(
            (size_t)capacity * sizeof *targets);
        if (!targets) {
            targets = inline_targets;
            capacity = GM_MOB_CAPACITY;
        }
    }
    *count = gm_mobs_explosion_targets(
        &r->mobs, r->dimension, targets, capacity);
    return targets;
}

static int runtime_controlled_tnt_precedes_mob(const GmRuntime *r)
{
    GmMobExplosionTarget inline_targets[GM_MOB_CAPACITY];
    GmMobExplosionTarget *targets;
    int first_mob_eid = 0;
    int first_tnt_eid = 0;
    long long first_mob_order = LLONG_MAX;
    long long first_tnt_order = LLONG_MAX;
    int count;
    if (!r || r->mobs_enabled || !r->controlled_mobs_enabled
            || r->primed_tnt_count <= 0)
        return 0;
    targets = runtime_living_targets(r, inline_targets, &count);
    if (!targets) return 0;
    for (int i = 0; i < count; ++i) {
        long long order = runtime_loaded_entity_order_key(
            r, targets[i].eid);
        if (order < first_mob_order) {
            first_mob_order = order;
            first_mob_eid = targets[i].eid;
        }
    }
    for (int i = 0; i < r->primed_tnt_cap; ++i) {
        const GmRuntimePrimedTnt *tnt = &r->primed_tnt[i];
        long long order;
        if (!tnt->active || tnt->dimension != r->dimension)
            continue;
        order = runtime_loaded_entity_order_key(r, tnt->eid);
        if (order < first_tnt_order) {
            first_tnt_order = order;
            first_tnt_eid = tnt->eid;
        }
    }
    /* Exact for bounded one-mob-or-boat/one-TNT saved-state rows. Interleaved
     * multi-entity ordering still needs an explicit loaded-entity order in
     * the state capsule rather than grouping by type. */
    int result = first_tnt_eid > 0 && first_mob_eid > 0
        && first_tnt_order < first_mob_order;
    if (targets != inline_targets) free(targets);
    return result;
}

static int runtime_controlled_item_precedes_tnt(const GmRuntime *r)
{
    int found_item = 0;
    int found_tnt = 0;
    long long first_item_order = LLONG_MAX;
    long long first_tnt_order = LLONG_MAX;
    if (!r || r->primed_tnt_count <= 0)
        return 0;
    for (int i = 0;
            i < gm_live_entity_slot_count(&r->entities); ++i) {
        const GmLiveEnt *item = gm_live_entity_ref(&r->entities, i);
        if (!item) continue;
        if (!item->active || item->type != 0
                || !item->controlled_stationary || item->eid < 0)
            continue;
        long long order = runtime_loaded_entity_order_key(r, item->eid);
        if (order < first_item_order) {
            first_item_order = order;
            found_item = 1;
        }
    }
    for (int i = 0; i < r->primed_tnt_cap; ++i) {
        const GmRuntimePrimedTnt *tnt = &r->primed_tnt[i];
        long long order;
        if (!tnt->active || tnt->dimension != r->dimension)
            continue;
        order = runtime_loaded_entity_order_key(r, tnt->eid);
        if (order < first_tnt_order) {
            first_tnt_order = order;
            found_tnt = 1;
        }
    }
    /* Exact for the bounded stationary-item/TNT saved-state row. General
     * interleaving still needs an explicit loaded-entity order. */
    return found_item && found_tnt
        && first_item_order < first_tnt_order;
}

static int runtime_controlled_tnt_precedes_falling(const GmRuntime *r)
{
    int first_falling_eid = 0;
    int first_tnt_eid = 0;
    long long first_falling_order = LLONG_MAX;
    long long first_tnt_order = LLONG_MAX;
    if (!r || r->falling_block_count <= 0 || r->primed_tnt_count <= 0)
        return 0;
    for (int i = 0; i < r->falling_blocks_cap; ++i) {
        const GmRuntimeFallingBlock *falling = &r->falling_blocks[i];
        if (!falling->active || falling->eid <= 0)
            continue;
        long long order = runtime_loaded_entity_order_key(r, falling->eid);
        if (order < first_falling_order) {
            first_falling_order = order;
            first_falling_eid = falling->eid;
        }
    }
    for (int i = 0; i < r->primed_tnt_cap; ++i) {
        const GmRuntimePrimedTnt *tnt = &r->primed_tnt[i];
        long long order;
        if (!tnt->active || tnt->dimension != r->dimension)
            continue;
        order = runtime_loaded_entity_order_key(r, tnt->eid);
        if (order < first_tnt_order) {
            first_tnt_order = order;
            first_tnt_eid = tnt->eid;
        }
    }
    /* Exact for the bounded one-falling-block/one-TNT proof. General loaded
     * entity interleaving still needs an explicit order in the capsule. */
    return first_tnt_eid > 0 && first_falling_eid > 0
        && first_tnt_order < first_falling_order;
}

static int runtime_controlled_tnt_precedes_small_fireball(const GmRuntime *r)
{
    int first_fireball_eid = 0;
    int first_tnt_eid = 0;
    long long first_fireball_order = LLONG_MAX;
    long long first_tnt_order = LLONG_MAX;
    if (!r || r->primed_tnt_count <= 0)
        return 0;
    for (int i = 0; i < r->projectiles_cap; ++i) {
        const GmRuntimeProjectile *fireball = &r->projectiles[i];
        if (!fireball->active || fireball->type != 3
                || fireball->eid <= 0)
            continue;
        long long order = runtime_loaded_entity_order_key(r, fireball->eid);
        if (order < first_fireball_order) {
            first_fireball_order = order;
            first_fireball_eid = fireball->eid;
        }
    }
    for (int i = 0; i < r->primed_tnt_cap; ++i) {
        const GmRuntimePrimedTnt *tnt = &r->primed_tnt[i];
        long long order;
        if (!tnt->active || tnt->dimension != r->dimension)
            continue;
        order = runtime_loaded_entity_order_key(r, tnt->eid);
        if (order < first_tnt_order) {
            first_tnt_order = order;
            first_tnt_eid = tnt->eid;
        }
    }
    /* Exact for the bounded one-small-fireball/one-TNT proof. */
    return first_tnt_eid > 0 && first_fireball_eid > 0
        && first_tnt_order < first_fireball_order;
}

