static int runtime_checkpoint_write_template_entities(
        FILE *stream, const GmMobTemplateEntity *entities, int count) {
    if (!runtime_checkpoint_write_u64(stream, (uint64_t)count)
            || !runtime_checkpoint_write_u64(
                stream, sizeof(GmMobTemplateEntity)))
        return 0;
    for (int index = 0; index < count; ++index) {
        GmMobTemplateEntity value = entities[index];
        value.minecart_spawner_potentials = NULL;
        if (fwrite(&value, sizeof value, 1, stream) != 1
                || !runtime_checkpoint_write_plain(
                    stream, entities[index].minecart_spawner_potentials,
                    (uint64_t)entities[index]
                        .minecart_spawner_potential_cap,
                    sizeof(GmSpawnerPotential)))
            return 0;
    }
    return 1;
}

