int gm_runtime_tape_merchant(
        GmRuntime *r, int selected, int offer_count, int disabled,
        ICStack buy_a, ICStack buy_b, ICStack sell) {
    if (!r || offer_count <= 0 || offer_count > VT_MAX_OFFERS
            || selected < 0 || selected >= offer_count
            || (disabled != 0 && disabled != 1)
            || !tape_stack_valid(buy_a.item, buy_a.count, buy_a.meta)
            || !tape_stack_valid(buy_b.item, buy_b.count, buy_b.meta)
            || !tape_stack_valid(sell.item, sell.count, sell.meta)
            || sell.count <= 0)
        return 0;
    r->tape_merchant_active = 1;
    r->tape_merchant_selected = selected;
    r->tape_merchant_offer_count = offer_count;
    r->tape_merchant_disabled = disabled;
    r->tape_merchant_offer[0] = buy_a.count ? buy_a : ic_empty();
    r->tape_merchant_offer[1] = buy_b.count ? buy_b : ic_empty();
    r->tape_merchant_offer[2] = sell;
    return 1;
}

int gm_runtime_tape_inventory(GmRuntime *r, int slot, int item, int count, int meta) {
    if (!r || !isr_slot_ok(slot) ||
        item < 0 || item > 4095 || count < 0 || count > 64 ||
        meta < 0 || meta > 32767 || ((item == 0) != (count == 0))) return 0;
    if (!r->tape_inv_active) {
        isr_init(&r->tape_inv);
        r->tape_inv_active = 1;
    }
    isr_set_stack(&r->tape_inv, slot,
                  count == 0 ? ic_empty() : ic_mk(item, count, meta));
    return 1;
}

