int gm_runtime_set_arrow_payload(
        GmRuntime *r, int eid, int arrow_kind, int potion_type,
        int spectral_duration, int color, int custom_color,
        const PtMobEffect *effects, int effect_count,
        const unsigned char *effect_flags,
        int pickup_item, int pickup_meta, int pickup_tag_id) {
    GmRuntimeProjectile *arrow = NULL;
    if (!r || eid <= 0 || arrow_kind < GM_ARROW_NORMAL
            || arrow_kind > GM_ARROW_SPECTRAL
            || potion_type < TB_PT_EMPTY || potion_type >= TB_PT_COUNT
            || spectral_duration < 0 || effect_count < 0
            || effect_count > GM_RUNTIME_ARROW_EFFECTS
            || (effect_count > 0 && (!effects || !effect_flags))
            || (custom_color != 0 && custom_color != 1)
            || pickup_meta < 0 || pickup_meta > 32767
            || !runtime_checkpoint_tag_id_valid(r, pickup_tag_id))
        return 0;
    if ((arrow_kind == GM_ARROW_NORMAL
                && (potion_type != TB_PT_EMPTY || effect_count != 0
                    || color != -1 || custom_color
                    || pickup_item != 262 || pickup_meta != 0
                    || pickup_tag_id != 0))
            || (arrow_kind == GM_ARROW_SPECTRAL
                && (potion_type != TB_PT_EMPTY || effect_count != 0
                    || color != -1 || custom_color
                    || pickup_item != 439 || pickup_meta != 0
                    || pickup_tag_id != 0))
            || (arrow_kind == GM_ARROW_TIPPED
                && (color < -1 || (pickup_item != 262 && pickup_item != 440)
                    || (pickup_item == 262
                        && (potion_type != TB_PT_EMPTY
                            || effect_count != 0 || pickup_tag_id != 0)))))
        return 0;
    for (int index = 0; index < effect_count; ++index)
        if (effects[index].id <= 0 || effects[index].id > 27
                || effects[index].amplifier < 0
                || effects[index].amplifier > 255
                || effects[index].duration <= 0
                || (effect_flags[index] & ~3u) != 0)
            return 0;
    for (int index = 0; index < r->projectiles_cap; ++index)
        if (r->projectiles[index].active
                && r->projectiles[index].eid == eid
                && (r->projectiles[index].type == 1
                    || r->projectiles[index].type == 2)) {
            arrow = &r->projectiles[index];
            break;
        }
    if (!arrow) return 0;
    arrow->arrow_kind = arrow_kind;
    arrow->arrow_potion_type = potion_type;
    arrow->arrow_spectral_duration = spectral_duration;
    arrow->arrow_color = color;
    arrow->arrow_custom_color = custom_color;
    arrow->arrow_pickup_item = pickup_item;
    arrow->arrow_pickup_meta = pickup_meta;
    arrow->arrow_pickup_tag_id = pickup_tag_id;
    arrow->arrow_effect_count = effect_count;
    memset(arrow->arrow_effects, 0, sizeof arrow->arrow_effects);
    memset(arrow->arrow_effect_flags, 0, sizeof arrow->arrow_effect_flags);
    if (effect_count > 0) {
        memcpy(arrow->arrow_effects, effects,
               (size_t)effect_count * sizeof effects[0]);
        memcpy(arrow->arrow_effect_flags, effect_flags,
               (size_t)effect_count * sizeof effect_flags[0]);
    }
    return 1;
}

