static int runtime_end_crystals_reserve(GmRuntime *r, int need) {
    int cap;
    GmRuntimeEndCrystal *grown;
    if (!r || need < 0 || need > 1048576) return 0;
    if (need <= r->end_crystals_cap) return 1;
    cap = r->end_crystals_cap > 0
        ? r->end_crystals_cap : GM_RUNTIME_END_CRYSTALS;
    while (cap < need) {
        if (cap > 1048576 / 2) {
            cap = 1048576;
            break;
        }
        cap *= 2;
    }
    grown = (GmRuntimeEndCrystal *)realloc(
        r->end_crystals, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + r->end_crystals_cap, 0,
           (size_t)(cap - r->end_crystals_cap) * sizeof *grown);
    r->end_crystals = grown;
    r->end_crystals_cap = cap;
    return 1;
}

