static int runtime_wither_drop_nether_star(
        GmRuntime *r, GmRuntimeWither *wither) {
    JavaRandom entity_random;
    float hover, yaw;
    double motion_x, motion_z;
    int64_t uuid_most, uuid_least;
    int eid;
    if (!r || !wither || !r->do_mob_loot || wither->nether_star_dropped)
        return 1;
    if (r->loaded_entity_order_count >= GM_RUNTIME_COLD_STORE_MAX)
        return 0;
    hover = (float)(runtime_math_random_next_double(r) * (MC_PI * 2.0));
    yaw = (float)(runtime_math_random_next_double(r) * 360.0);
    motion_x = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    motion_z = (double)(float)(runtime_math_random_next_double(r)
        * 0.20000000298023224 - 0.10000000149011612);
    eid = r->next_entity_id++;
    jrand_set(&entity_random, runtime_java_random_seed_next_long(
        &r->entity_seed_generator_seed48));
    runtime_next_server_uuid(r, &uuid_most, &uuid_least);
    if (!gm_live_spawn_item_exact_hover(
            &r->entities, eid, wither->x, wither->y, wither->z,
            motion_x, 0.20000000298023224, motion_z, yaw, hover,
            399, 1, 0, -6000, 10, 0)) {
        --r->next_entity_id;
        return 0;
    }
    if (!gm_live_set_item_environment_state(
            &r->entities, eid, entity_random.seed, -1, 0, 1)
            || !gm_runtime_set_item_entity_uuid(
                r, eid, uuid_most, uuid_least)
            || !runtime_loaded_entity_order_append(r, eid))
        return 0;
    wither->nether_star_dropped = 1;
    return 1;
}

static double runtime_wither_random_double(GmRuntimeWither *wither) {
    uint64_t high = (uint64_t)runtime_java_random_seed_next(
        &wither->random_seed48, 26);
    uint64_t low = (uint64_t)runtime_java_random_seed_next(
        &wither->random_seed48, 27);
    return (double)((high << 27) + low)
        / (double)(UINT64_C(1) << 53);
}

static float runtime_wither_sound_pitch(GmRuntimeWither *wither) {
    float first = runtime_java_random_seed_next_float(
        &wither->random_seed48);
    float second = runtime_java_random_seed_next_float(
        &wither->random_seed48);
    return (first - second) * 0.2F + 1.0F;
}

static int runtime_wither_damage_source(
        GmRuntime *r, int eid, float amount, int source_kind,
        int source_eid, int source_is_player,
        double source_x, double source_z) {
    GmRuntimeWither *wither = runtime_wither_by_eid(r, eid);
    float applied;
    int fresh_hit;
    if (!wither || !isfinite(amount) || amount <= 0.0F
            || source_kind < 0 || source_kind > 3
            || source_eid < 0
            || (source_is_player != 0 && source_is_player != 1)
            || !isfinite(source_x) || !isfinite(source_z)
            || wither->health <= 0.0F || wither->death_time > 0)
        return 0;
    /* 0 generic/player, 1 arrow, 2 undead/wither, 3 out-of-world. */
    if ((wither->invul_time > 0 && source_kind != 3)
            || (wither->health <= 150.0F && source_kind == 1)
            || source_kind == 2)
        return 0;
    fresh_hit = wither->hurt_resistant_time <= 10;
    if (!fresh_hit) {
        /* EntityLivingBase compares raw incoming damage with lastDamage,
         * then sends only the raw delta through damageEntity. CombatRules'
         * nonlinear armor transform must happen after that comparison. */
        if (amount <= wither->last_damage) return 0;
        applied = amount - wither->last_damage;
    } else {
        applied = amount;
    }
    wither->last_damage = amount;
    if (source_kind != 3) {
        float armor_after = 4.0F - applied / 2.0F;
        if (armor_after < 0.8F) armor_after = 0.8F;
        if (armor_after > 20.0F) armor_after = 20.0F;
        applied *= 1.0F - armor_after / 25.0F;
    }
    wither->health -= applied;
    if (fresh_hit) {
        wither->hurt_resistant_time = 20;
        wither->hurt_time = 10;
    }
    if (wither->block_break_counter <= 0)
        wither->block_break_counter = 20;
    wither->idle_head_updates[0] += 3;
    wither->idle_head_updates[1] += 3;
    if (source_is_player || source_eid > 0) {
        wither->revenge_eid = source_eid;
        wither->revenge_is_player = source_is_player;
        wither->revenge_timer = wither->ticks_existed;
    }
    if (source_is_player) {
        wither->recently_hit = 100;
        wither->attacking_player = 1;
    }
    if (fresh_hit) {
        if (source_is_player || source_eid > 0) {
            double dx = source_x - wither->x;
            double dz = source_z - wither->z;
            double length;
            /* setBeenAttacked and knockBack each sample the target's
             * knockback-resistance attribute, even when it is exactly zero. */
            (void)runtime_wither_random_double(wither);
            while (dx * dx + dz * dz < 1.0e-4) {
                dx = (runtime_math_random_next_double(r)
                    - runtime_math_random_next_double(r)) * 0.01;
                dz = (runtime_math_random_next_double(r)
                    - runtime_math_random_next_double(r)) * 0.01;
            }
            length = (double)(float)sqrt(dx * dx + dz * dz);
            (void)runtime_wither_random_double(wither);
            wither->vx /= 2.0;
            wither->vz /= 2.0;
            wither->vx -= dx / length * (double)0.4F;
            wither->vz -= dz / length * (double)0.4F;
            if (wither->on_ground) {
                wither->vy /= 2.0;
                wither->vy += (double)0.4F;
                if (wither->vy > 0.4000000059604645)
                    wither->vy = 0.4000000059604645;
            }
        } else {
            (void)runtime_math_random_next_double(r);
        }
    }
    if (wither->health <= 0.0F) {
        wither->health = 0.0F;
        wither->death_time = 0;
        if (fresh_hit)
            runtime_sound_event_append(
                r, GM_SOUND_WITHER_DEATH, GM_SOUND_CATEGORY_HOSTILE,
                wither->eid, 0, wither->x, wither->y, wither->z,
                1.0F, runtime_wither_sound_pitch(wither));
        (void)runtime_wither_drop_nether_star(r, wither);
    } else if (fresh_hit) {
        wither->living_sound_time = -80;
        runtime_sound_event_append(
            r, GM_SOUND_WITHER_HURT, GM_SOUND_CATEGORY_HOSTILE,
            wither->eid, 0, wither->x, wither->y, wither->z,
            1.0F, runtime_wither_sound_pitch(wither));
    }
    return 1;
}

int gm_runtime_wither_damage_fixture(
        GmRuntime *r, int eid, float amount, int source_kind) {
    if (!r) return 0;
    int source_eid = source_kind == 0 || source_kind == 1
        ? r->player_entity_id : 0;
    int source_is_player = source_kind == 0 || source_kind == 1;
    double source_x = source_is_player
        ? r->server_player.ent.posX + (double)r->ox : 0.0;
    double source_z = source_is_player
        ? r->server_player.ent.posZ + (double)r->oz : 0.0;
    return runtime_wither_damage_source(
        r, eid, amount, source_kind,
        source_eid, source_is_player, source_x, source_z);
}

static int runtime_player_attack_wither(GmRuntime *r) {
    const double border = 0.1;
    const double half_width = (double)0.9F * 0.5;
    const double height = (double)3.5F;
    double sx, sy, sz, dx, dy, dz, nearest = PSV_REACH;
    GmRuntimeWither *hit = NULL;
    float f, f1, f2, f3;
    int full_strength = 0, sprint_knockback = 0;
    float amount;
    if (!r || r->wither_count <= 0) return 0;
    f = mc_cos(&r->sin_table,
        -r->player.yaw * 0.017453292F - 3.1415927F);
    f1 = mc_sin(&r->sin_table,
        -r->player.yaw * 0.017453292F - 3.1415927F);
    f2 = -mc_cos(&r->sin_table, -r->player.pitch * 0.017453292F);
    f3 = mc_sin(&r->sin_table, -r->player.pitch * 0.017453292F);
    dx = (double)(f1 * f2);
    dy = (double)f3;
    dz = (double)(f * f2);
    sx = r->player.ent.posX + (double)r->ox;
    sy = r->player.ent.posY + psv_player_eye_height(&r->player);
    sz = r->player.ent.posZ + (double)r->oz;
    for (int index = 0; index < r->withers_cap; ++index) {
        GmRuntimeWither *candidate = &r->withers[index];
        double t0 = 0.0, t1 = nearest;
        if (!candidate->active || candidate->dimension != r->dimension
                || candidate->health <= 0.0F)
            continue;
        if (ray_axis(sx, dx,
                     candidate->x - half_width - border,
                     candidate->x + half_width + border, &t0, &t1)
                && ray_axis(sy, dy,
                     candidate->y - border,
                     candidate->y + height + border, &t0, &t1)
                && ray_axis(sz, dz,
                     candidate->z - half_width - border,
                     candidate->z + half_width + border, &t0, &t1)
                && t0 <= nearest) {
            nearest = t0;
            hit = candidate;
        }
    }
    if (!hit) return 0;
    amount = gm_mobs_player_attack_amount_undefined(
        &r->mobs, (const struct PsvPlayer *)&r->player,
        runtime_attack_potion_bonus(r),
        r->player_attack_speed_multiplier,
        &full_strength, &sprint_knockback);
    (void)sprint_knockback;
    if (amount > 0.0F
            && gm_runtime_wither_damage_fixture(r, hit->eid, amount, 0)) {
        pv_add_exhaustion(&r->vitals, 0.1F);
        runtime_sound_event_append(
            r, full_strength ? GM_SOUND_PLAYER_ATTACK_STRONG
                             : GM_SOUND_PLAYER_ATTACK_WEAK,
            GM_SOUND_CATEGORY_PLAYERS, 0, 0,
            sx, r->server_player.ent.posY, sz, 1.0F, 1.0F);
    } else {
        runtime_sound_event_append(
            r, GM_SOUND_PLAYER_ATTACK_NODAMAGE,
            GM_SOUND_CATEGORY_PLAYERS, 0, 0,
            sx, r->server_player.ent.posY, sz, 1.0F, 1.0F);
    }
    return 1;
}

int gm_runtime_wither_count(const GmRuntime *r) {
    return r ? r->wither_count : 0;
}

int gm_runtime_wither_get(
        const GmRuntime *r, int index, GmRuntimeWither *out) {
    if (!r || !out || index < 0) return 0;
    for (int i = 0; i < r->withers_cap; ++i) {
        if (!r->withers[i].active) continue;
        if (index-- == 0) {
            *out = r->withers[i];
            return 1;
        }
    }
    return 0;
}

int gm_runtime_spawn_wither_skull_fixture(
        GmRuntime *r, int eid, int shooter_eid,
        double x, double y, double z, double vx, double vy, double vz,
        double ax, double ay, double az, float yaw, float pitch,
        int invulnerable, int ticks_in_air, int life) {
    if (!r || eid < 0 || shooter_eid < 0
            || !isfinite(x) || !isfinite(y) || !isfinite(z)
            || !isfinite(vx) || !isfinite(vy) || !isfinite(vz)
            || !isfinite(ax) || !isfinite(ay) || !isfinite(az)
            || !isfinite(yaw) || !isfinite(pitch)
            || (invulnerable != 0 && invulnerable != 1)
            || ticks_in_air < 0 || life < 0
            || r->loaded_entity_order_count
                >= GM_RUNTIME_COLD_STORE_MAX)
        return 0;
    {
        GmRuntimeProjectile *skull = runtime_projectile_free_slot(r);
        if (!skull) return 0;
        memset(skull, 0, sizeof *skull);
        skull->active = 1;
        skull->type = 10;
        skull->dimension = r->dimension;
        skull->eid = eid;
        skull->shooting_living = shooter_eid > 0;
        skull->shooter_eid = shooter_eid;
        skull->wither_shooter_eid = shooter_eid;
        skull->x = x;
        skull->y = y;
        skull->z = z;
        skull->vx = vx;
        skull->vy = vy;
        skull->vz = vz;
        skull->ax = ax;
        skull->ay = ay;
        skull->az = az;
        skull->yaw = yaw;
        skull->pitch = pitch;
        skull->wither_invulnerable = invulnerable;
        skull->wither_ticks_in_air = ticks_in_air;
        skull->wither_life = life;
        if (!runtime_loaded_entity_order_append(r, eid)) {
            memset(skull, 0, sizeof *skull);
            return 0;
        }
        if (eid >= r->next_entity_id) r->next_entity_id = eid + 1;
        return 1;
    }
    return 0;
}

