int gm_runtime_set_area_effect_cloud_kinematics(
        GmRuntime *r, int eid, double vx, double vy, double vz,
        float yaw, float pitch, float prev_yaw, float prev_pitch) {
    if (!r || eid <= 0 || !isfinite(vx) || !isfinite(vy) || !isfinite(vz)
            || !isfinite(yaw) || !isfinite(pitch)
            || !isfinite(prev_yaw) || !isfinite(prev_pitch))
        return 0;
    for (int index = 0; index < r->area_effect_clouds_cap; ++index) {
        GmRuntimeAreaEffectCloud *cloud = &r->area_effect_clouds[index];
        if (!cloud->state.active || cloud->eid != eid) continue;
        cloud->vx = vx;
        cloud->vy = vy;
        cloud->vz = vz;
        cloud->yaw = yaw;
        cloud->pitch = pitch;
        cloud->prev_yaw = prev_yaw;
        cloud->prev_pitch = prev_pitch;
        return 1;
    }
    return 0;
}

int gm_runtime_set_area_effect_cloud_deadline(
        GmRuntime *r, int cloud_eid, int target_eid, int deadline) {
    if (!r || cloud_eid <= 0 || target_eid < 0 || deadline <= 0)
        return 0;
    for (int index = 0; index < r->area_effect_clouds_cap; ++index) {
        GmRuntimeAreaEffectCloud *cloud = &r->area_effect_clouds[index];
        if (!cloud->state.active || cloud->eid != cloud_eid) continue;
        if (target_eid == r->player_entity_id) {
            cloud->state.next_application = deadline;
            return 1;
        }
        if (gm_mobs_find_slot_by_eid(&r->mobs, target_eid) < 0)
            return 0;
        return runtime_area_effect_cooldown_set(
            r, cloud_eid, target_eid, deadline);
    }
    return 0;
}

int gm_runtime_area_effect_cloud_deadline(
        const GmRuntime *r, int cloud_eid, int target_eid) {
    if (!r || cloud_eid <= 0 || target_eid <= 0) return 0;
    return runtime_area_effect_cooldown_deadline(
        r, cloud_eid, target_eid);
}

int gm_runtime_set_area_effect_cloud_identity(
        GmRuntime *r, int cloud_eid,
        long long uuid_most, long long uuid_least,
        int owner_present, int owner_eid,
        long long owner_uuid_most, long long owner_uuid_least) {
    if (!r || cloud_eid <= 0
            || (owner_present != 0 && owner_present != 1)
            || (owner_present && owner_eid < 0)
            || (!owner_present && (owner_eid != -1
                || owner_uuid_most != 0 || owner_uuid_least != 0)))
        return 0;
    for (int index = 0; index < r->area_effect_clouds_cap; ++index) {
        GmRuntimeAreaEffectCloud *cloud = &r->area_effect_clouds[index];
        if (!cloud->state.active || cloud->eid != cloud_eid) continue;
        cloud->uuid_present = 1;
        cloud->uuid_most = uuid_most;
        cloud->uuid_least = uuid_least;
        cloud->owner_present = owner_present;
        cloud->owner_eid = owner_eid;
        cloud->owner_uuid_most = owner_uuid_most;
        cloud->owner_uuid_least = owner_uuid_least;
        cloud->player_owner = owner_present
            && owner_eid == r->player_entity_id;
        return 1;
    }
    return 0;
}

int gm_runtime_set_area_effect_cloud_random_seed48(
        GmRuntime *r, int eid, uint64_t seed48) {
    if (!r || eid <= 0 || seed48 > GM_JAVA_RANDOM_MASK) return 0;
    for (int i = 0; i < r->area_effect_clouds_cap; ++i) {
        GmRuntimeAreaEffectCloud *cloud = &r->area_effect_clouds[i];
        if (!cloud->state.active || cloud->eid != eid) continue;
        cloud->random_seed48 = seed48;
        return 1;
    }
    return 0;
}

int gm_runtime_set_area_effect_cloud_common_state(
        GmRuntime *r, int eid,
        int dimension, int air, int fire_ticks, int portal_cooldown,
        int on_ground, int no_gravity, int invulnerable, int silent,
        int glowing, int update_blocked, int in_water, int first_update,
        float fall_distance,
        double prev_x, double prev_y, double prev_z,
        double last_tick_x, double last_tick_y, double last_tick_z,
        uint64_t server_random_seed48, int server_random_have_gaussian,
        double server_random_gaussian) {
    if (!r || eid <= 0 || dimension != r->dimension
            || air < -32768 || air > 32767
            || fire_ticks < -32768 || fire_ticks > 32767
            || portal_cooldown < 0
            || (on_ground != 0 && on_ground != 1)
            || (no_gravity != 0 && no_gravity != 1)
            || (invulnerable != 0 && invulnerable != 1)
            || (silent != 0 && silent != 1)
            || (glowing != 0 && glowing != 1)
            || (update_blocked != 0 && update_blocked != 1)
            || (in_water != 0 && in_water != 1)
            || (first_update != 0 && first_update != 1)
            || !isfinite(fall_distance) || fall_distance < 0.0F
            || !isfinite(prev_x) || !isfinite(prev_y) || !isfinite(prev_z)
            || !isfinite(last_tick_x) || !isfinite(last_tick_y)
            || !isfinite(last_tick_z)
            || server_random_seed48 > GM_JAVA_RANDOM_MASK
            || (server_random_have_gaussian != 0
                && server_random_have_gaussian != 1)
            || !isfinite(server_random_gaussian))
        return 0;
    for (int i = 0; i < r->area_effect_clouds_cap; ++i) {
        GmRuntimeAreaEffectCloud *cloud = &r->area_effect_clouds[i];
        if (!cloud->state.active || cloud->eid != eid) continue;
        cloud->dimension = dimension;
        cloud->air = air;
        cloud->fire_ticks = fire_ticks;
        cloud->portal_cooldown = portal_cooldown;
        cloud->on_ground = on_ground;
        cloud->no_gravity = no_gravity;
        cloud->invulnerable = invulnerable;
        cloud->silent = silent;
        cloud->glowing = glowing;
        cloud->update_blocked = update_blocked;
        cloud->in_water = in_water;
        cloud->first_update = first_update;
        cloud->fall_distance = fall_distance;
        cloud->prev_x = prev_x;
        cloud->prev_y = prev_y;
        cloud->prev_z = prev_z;
        cloud->last_tick_x = last_tick_x;
        cloud->last_tick_y = last_tick_y;
        cloud->last_tick_z = last_tick_z;
        cloud->server_random_seed48 = server_random_seed48;
        cloud->server_random_have_gaussian =
            server_random_have_gaussian;
        cloud->server_random_gaussian = server_random_gaussian;
        return 1;
    }
    return 0;
}

int gm_runtime_spawn_mob_fixture(
        GmRuntime *r, int type, int eid, double x, double y, double z,
        double vx, double vy, double vz, float yaw, float health, int no_ai,
        int hurt_time, int death_time, int hurt_resistant_time) {
    if (!r || r->loaded_entity_order_count
            >= GM_RUNTIME_COLD_STORE_MAX)
        return 0;
    r->mobs.active_dimension = r->dimension;
    int slot = gm_mobs_spawn_exact(
        &r->mobs, type, eid, x, y, z, vx, vy, vz, yaw, health, no_ai,
        hurt_time, death_time, hurt_resistant_time);
    if (slot < 0) return 0;
    if (!runtime_loaded_entity_order_append(r, eid)) return 0;
    r->controlled_mobs_enabled = 1;
    return 1;
}

int gm_runtime_spawn_horse_fixture(
        GmRuntime *r, int type, int eid,
        double x, double y, double z, double vx, double vy, double vz,
        float yaw, float health, int no_ai,
        double max_health_value, double movement_speed,
        double jump_strength, int growing_age, int status, int temper,
        int variant, int armor, int chested, int trap, int trap_time,
        int hurt_time, int death_time, int hurt_resistant_time) {
    if (!r || r->loaded_entity_order_count
            >= GM_RUNTIME_COLD_STORE_MAX
            || hurt_time < 0 || hurt_time > 10
            || death_time < 0 || death_time >= 20
            || hurt_resistant_time < 0 || hurt_resistant_time > 20)
        return 0;
    r->mobs.active_dimension = r->dimension;
    int slot = gm_mobs_spawn_horse_exact(
        &r->mobs, type, eid, x, y, z, vx, vy, vz, yaw, health, no_ai,
        max_health_value, movement_speed, jump_strength, growing_age,
        status, temper, variant, armor, chested, trap, trap_time);
    if (slot < 0 || !runtime_loaded_entity_order_append(r, eid)) return 0;
    r->mobs.entity_hurt_time[slot] = hurt_time;
    r->mobs.entity_death_time[slot] = death_time;
    r->mobs.entity_hurt_resistant[slot] = hurt_resistant_time;
    r->controlled_mobs_enabled = 1;
    return 1;
}

