int gm_runtime_set_horse_inventory(
        GmRuntime *r, int eid, int inventory_slot, ICStack stack) {
    int slot, ticks, result;
    if (!r) return 0;
    slot = gm_mobs_find_slot_by_eid(&r->mobs, eid);
    if (slot <= 0) return 0;
    /* This wrapper is the cold fixture/save restore path. Java does not replay
     * InventoryBasic change sounds when continuing an already captured tick. */
    ticks = r->mobs.entity_ticks_existed[slot];
    r->mobs.entity_ticks_existed[slot] = 0;
    result = gm_mobs_set_horse_inventory(
        &r->mobs, eid, inventory_slot, stack);
    r->mobs.entity_ticks_existed[slot] = ticks;
    return result;
}

