int gm_runtime_restore_mob_health_absorption(
        GmRuntime *r, int eid, float health, float absorption) {
    EwStore *now, *next;
    int slot;
    float maximum;
    if (!r || !isfinite(health) || !isfinite(absorption)
            || health < 0.0F || absorption < 0.0F)
        return 0;
    slot = gm_mobs_find_slot_by_eid(&r->mobs, eid);
    if (slot <= 0) return 0;
    maximum = gm_mobs_max_health(&r->mobs, slot);
    if (health > maximum) return 0;
    now = r->mobs.current ? &r->mobs.b : &r->mobs.a;
    next = r->mobs.current ? &r->mobs.a : &r->mobs.b;
    now->health[slot] = health;
    next->health[slot] = health;
    r->mobs.entity_absorption[slot] = absorption;
    return 1;
}

