static int runtime_replaceitem_output_is(
        const char *value, const RuntimeReplaceItemCommand *command) {
    char prefix[768];
    static const char suffix[] = "] \"}";
    int written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"commands.replaceitem.success\","
        "\"with\":[\"%s\",\"%d\",{\"color\":\"white\","
        "\"hoverEvent\":{\"action\":\"show_item\",\"value\":{"
        "\"text\":\"{id:\\\"%s\\\",Count:%db,Damage:%ds}\"}},"
        "\"extra\":[{\"text\":\"%s\"},{\"text\":\"]\"}],"
        "\"text\":\"[\"}]}],\"text\":\"[",
        command ? command->slot_name : "", command ? command->count : 0,
        command ? command->name : "", command ? command->count : 0,
        command ? command->meta : 0, command ? command->display : "");
    size_t prefix_length;
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

static int runtime_enchant_execute(
        GmRuntime *r, const RuntimeEnchantCommand *command) {
    ICStack stack;
    int slot;
    if (!r || !command) return 0;
    slot = r->player.inv.current_item;
    stack = isr_get_stack(&r->player.inv, slot);
    if (stack.item == 0 || stack.count <= 0
            || !gm_enchantment_can_apply(command->id, stack.item)
            || stack.n_enchants >= IC_MAX_ENCHANTS)
        return 0;
    for (int index = 0; index < stack.n_enchants; ++index)
        if (!gm_enchantments_compatible(
                command->id, stack.enchants[index].id)) return 0;
    stack.enchants[stack.n_enchants].id = command->id;
    stack.enchants[stack.n_enchants].level = command->level;
    ++stack.n_enchants;
    isr_set_stack(&r->player.inv, slot, stack);
    return 1;
}

static int runtime_give_output_is(
        const char *value, const char *player_name,
        const RuntimeGiveCommand *command) {
    char prefix[768];
    static const char suffix[] = "] \"}";
    int written;
    size_t prefix_length;
    if (!player_name || !command || !command->name || !command->display)
        return 0;
    written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"commands.give.success\","
        "\"with\":[{\"color\":\"white\",\"hoverEvent\":{"
        "\"action\":\"show_item\",\"value\":{\"text\":"
        "\"{id:\\\"%s\\\",Count:1b,Damage:%ds}\"}},"
        "\"extra\":[{\"text\":\"%s\"},{\"text\":\"]\"}],"
        "\"text\":\"[\"},\"%d\",\"%s\"]}],\"text\":\"[",
        command->name, command->meta,
        command->display, command->count, player_name);
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

static int runtime_give_execute(
        GmRuntime *r, const RuntimeGiveCommand *command) {
    ICStack stack;
    ICStack held;
    if (!r || !command) return 0;
    held = isr_get_stack(&r->player.inv, r->player.inv.current_item);
    stack = ic_mk(command->item, command->count, command->meta);
    if (!isr_add_item_stack_to_inventory(&r->player.inv, &stack)
            || stack.count != 0) return 0;
    if (held.item == 0)
        r->mobs.player_ticks_since_last_swing = -1;
    return 1;
}

