typedef struct {
    int kind, fade_in, stay, fade_out;
} RuntimeTitleCommand;

static int runtime_parse_single_player_title_command(
        const char *value, RuntimeTitleCommand *out) {
    char copy[256], *words[7], *save = NULL, *word;
    int count = 0;
    if (!value || !out || strlen(value) >= sizeof copy) return 0;
    snprintf(copy, sizeof copy, "%s", value);
    for (word = strtok_r(copy, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= 7) return 0;
        words[count++] = word;
    }
    memset(out, 0, sizeof *out);
    if (count < 3 || strcasecmp(words[0], "title")
            || strcasecmp(words[1], "@p")) return 0;
    if ((!strcasecmp(words[2], "clear")
            || !strcasecmp(words[2], "reset")) && count == 3) {
        out->kind = !strcasecmp(words[2], "clear") ? 5 : 6;
        return 1;
    }
    if (!strcasecmp(words[2], "times") && count == 6
            && runtime_parse_decimal_range(
                words[3], INT_MIN, INT_MAX, &out->fade_in)
            && runtime_parse_decimal_range(
                words[4], INT_MIN, INT_MAX, &out->stay)
            && runtime_parse_decimal_range(
                words[5], INT_MIN, INT_MAX, &out->fade_out)) {
        out->kind = 4;
        return 1;
    }
    if (count == 4 && !strcmp(words[3], "{\"text\":\"bounded\"}")) {
        if (!strcasecmp(words[2], "title")) out->kind = 1;
        else if (!strcasecmp(words[2], "subtitle")) out->kind = 2;
        else if (!strcasecmp(words[2], "actionbar")) out->kind = 3;
        return out->kind != 0;
    }
    return 0;
}

typedef struct {
    const char *category;
    char sound[128];
} RuntimeStopSoundCommand;

static int runtime_parse_single_player_stopsound_command(
        const char *value, RuntimeStopSoundCommand *out) {
    static const char *const categories[10] = {
        "master", "music", "record", "weather", "block",
        "hostile", "neutral", "player", "ambient", "voice"
    };
    char copy[256], *words[5], *save = NULL, *word;
    int count = 0;
    if (!value || !out || strlen(value) >= sizeof copy) return 0;
    snprintf(copy, sizeof copy, "%s", value);
    for (word = strtok_r(copy, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= 5) return 0;
        words[count++] = word;
    }
    memset(out, 0, sizeof *out);
    if (count < 2 || count > 4 || strcasecmp(words[0], "stopsound")
            || strcasecmp(words[1], "@p")) return 0;
    if (count >= 3) {
        for (int index = 0; index < 10; ++index)
            if (!strcasecmp(words[2], categories[index]))
                out->category = categories[index];
        if (!out->category) return 0;
    }
    if (count == 4) {
        if (!words[3][0] || snprintf(out->sound, sizeof out->sound,
                "%s", words[3]) >= (int)sizeof out->sound) return 0;
    }
    return 1;
}

