static int runtime_parse_decimal_range(
        const char *text, int minimum, int maximum, int *out) {
    char *end = NULL;
    long value;
    if (!text || !*text || !out) return 0;
    value = strtol(text, &end, 10);
    if (!end || *end || value < minimum || value > maximum) return 0;
    *out = (int)value;
    return 1;
}

static int runtime_potion_id(const char *text) {
    int id = 0;
    const char *name = text;
    if (runtime_parse_decimal_range(text, 1, 27, &id)) return id;
    if (!text) return 0;
    if (!strncasecmp(text, "minecraft:", 10)) name = text + 10;
    for (id = 1; id <= 27; ++id)
        if (!strcasecmp(name, runtime_potion_specs[id].name)) return id;
    return 0;
}

static int runtime_parse_single_player_effect_command(
        const char *value, RuntimeEffectCommand *out) {
    char buffer[256], *tokens[7], *save = NULL, *word;
    int count = 0, id, seconds = 30, amplifier = 0, show_particles = 1;
    if (!value || !out || strlen(value) >= sizeof buffer) return 0;
    snprintf(buffer, sizeof buffer, "%s", value);
    for (word = strtok_r(buffer, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= 7) return 0;
        tokens[count++] = word;
    }
    if (count < 3 || strcasecmp(tokens[0], "effect")
            || strcasecmp(tokens[1], "@p")) return 0;
    memset(out, 0, sizeof *out);
    if (!strcasecmp(tokens[2], "clear")) {
        if (count != 3) return 0;
        out->kind = 3;
        return 1;
    }
    id = runtime_potion_id(tokens[2]);
    if (!id || count > 6) return 0;
    if (count >= 4
            && !runtime_parse_decimal_range(
                tokens[3], 0, 1000000, &seconds)) return 0;
    if (count >= 5
            && !runtime_parse_decimal_range(tokens[4], 0, 255, &amplifier))
        return 0;
    if (count >= 6) {
        if (!strcasecmp(tokens[5], "true")) show_particles = 0;
        else if (strcasecmp(tokens[5], "false")) return 0;
    }
    out->kind = seconds > 0 ? 1 : 2;
    out->id = id;
    out->seconds = seconds;
    out->amplifier = amplifier;
    out->show_particles = show_particles;
    return 1;
}

static int runtime_command_remove_potion(GmRuntime *r, int id) {
    int out = 0, removed = 0;
    if (!r || id < 1 || id > 27) return 0;
    for (int index = 0; index < r->potion_count; ++index) {
        GmPotionEffectView effect = r->potions[index];
        if (effect.id != id) {
            r->potions[out++] = effect;
            continue;
        }
        removed = 1;
        if (id == 22) {
            r->mobs.player_absorption -=
                4.0F * (float)(effect.amplifier + 1);
            if (r->mobs.player_absorption < 0.0F)
                r->mobs.player_absorption = 0.0F;
        }
    }
    if (!removed) return 0;
    r->potion_count = out;
    runtime_refresh_potion_attributes(r);
    if (id == 9) {
        r->player_time_in_portal = 0.0F;
        r->player_prev_time_in_portal = 0.0F;
    }
    return 1;
}

