static int runtime_parse_idempotent_server_mode_command(const char *value) {
    if (!value) return 0;
    if (!strcasecmp(value, "difficulty peaceful")) return 1;
    if (!strcasecmp(value, "difficulty easy")) return 2;
    if (!strcasecmp(value, "difficulty normal")) return 3;
    if (!strcasecmp(value, "difficulty hard")) return 4;
    if (!strcasecmp(value, "difficulty p")
            || !strcasecmp(value, "difficulty 0")) return 1;
    if (!strcasecmp(value, "difficulty e")
            || !strcasecmp(value, "difficulty 1")) return 2;
    if (!strcasecmp(value, "difficulty n")
            || !strcasecmp(value, "difficulty 2")) return 3;
    if (!strcasecmp(value, "difficulty h")
            || !strcasecmp(value, "difficulty 3")) return 4;
    if (!strcasecmp(value, "defaultgamemode survival")) return 5;
    if (!strcasecmp(value, "defaultgamemode creative")) return 6;
    if (!strcasecmp(value, "defaultgamemode adventure")) return 7;
    if (!strcasecmp(value, "defaultgamemode spectator")) return 8;
    if (!strcasecmp(value, "defaultgamemode 0")) return 5;
    if (!strcasecmp(value, "defaultgamemode 1")) return 6;
    if (!strcasecmp(value, "defaultgamemode 2")) return 7;
    return !strcasecmp(value, "defaultgamemode 3") ? 8 : 0;
}

enum {
    RUNTIME_WORLDBORDER_GET = 1,
    RUNTIME_WORLDBORDER_SET,
    RUNTIME_WORLDBORDER_ADD,
    RUNTIME_WORLDBORDER_CENTER,
    RUNTIME_WORLDBORDER_DAMAGE_BUFFER,
    RUNTIME_WORLDBORDER_DAMAGE_AMOUNT,
    RUNTIME_WORLDBORDER_WARNING_TIME,
    RUNTIME_WORLDBORDER_WARNING_DISTANCE
};

typedef struct {
    int kind;
    double first, second;
    long long duration_ms;
    int first_relative, second_relative;
} RuntimeWorldBorderCommand;

static int runtime_worldborder_double(
        const char *text, double minimum, double maximum, double *out) {
    char *end;
    double value;
    if (!text || !text[0]) return 0;
    errno = 0;
    value = strtod(text, &end);
    if (errno == ERANGE || end == text || *end || !isfinite(value)
            || value < minimum || value > maximum)
        return 0;
    *out = value;
    return 1;
}

static int runtime_worldborder_seconds(const char *text, long long *out) {
    char *end;
    long long value;
    if (!text || !text[0]) return 0;
    errno = 0;
    value = strtoll(text, &end, 10);
    if (errno == ERANGE || end == text || *end || value < 0
            || value > LLONG_MAX / 1000LL)
        return 0;
    *out = value * 1000LL;
    return 1;
}

static int runtime_worldborder_coordinate(
        const char *text, double *value, int *relative) {
    if (!text) return 0;
    *relative = text[0] == '~';
    if (*relative && !text[1]) {
        *value = 0.0;
        return 1;
    }
    return runtime_worldborder_double(
        text + (*relative ? 1 : 0), -30000000.0, 30000000.0, value);
}

static int runtime_parse_worldborder_command(
        const char *value, RuntimeWorldBorderCommand *parsed) {
    char buffer[160], *words[5], *save = NULL, *word;
    int count = 0;
    RuntimeWorldBorderCommand command = {0};
    if (!value || strlen(value) >= sizeof buffer) return 0;
    memcpy(buffer, value, strlen(value) + 1u);
    for (word = strtok_r(buffer, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= 5) return 0;
        words[count++] = word;
    }
    if (count < 2 || strcasecmp(words[0], "worldborder")) return 0;
    if (!strcasecmp(words[1], "get") && count == 2) {
        command.kind = RUNTIME_WORLDBORDER_GET;
    } else if (!strcasecmp(words[1], "set")
            && (count == 3 || count == 4)
            && runtime_worldborder_double(
                words[2], 1.0, 60000000.0, &command.first)
            && (count == 3 || runtime_worldborder_seconds(
                words[3], &command.duration_ms))) {
        command.kind = RUNTIME_WORLDBORDER_SET;
    } else if (!strcasecmp(words[1], "add")
            && (count == 3 || count == 4)
            && runtime_worldborder_double(
                words[2], -60000000.0, 60000000.0, &command.first)
            && (count == 3 || runtime_worldborder_seconds(
                words[3], &command.duration_ms))) {
        command.kind = RUNTIME_WORLDBORDER_ADD;
    } else if (!strcasecmp(words[1], "center") && count == 4
            && runtime_worldborder_coordinate(
                words[2], &command.first, &command.first_relative)
            && runtime_worldborder_coordinate(
                words[3], &command.second, &command.second_relative)) {
        command.kind = RUNTIME_WORLDBORDER_CENTER;
    } else if (!strcasecmp(words[1], "damage") && count == 4
            && !strcasecmp(words[2], "buffer")
            && runtime_worldborder_double(
                words[3], 0.0, DBL_MAX, &command.first)) {
        command.kind = RUNTIME_WORLDBORDER_DAMAGE_BUFFER;
    } else if (!strcasecmp(words[1], "damage") && count == 4
            && !strcasecmp(words[2], "amount")
            && runtime_worldborder_double(
                words[3], 0.0, DBL_MAX, &command.first)) {
        command.kind = RUNTIME_WORLDBORDER_DAMAGE_AMOUNT;
    } else if (!strcasecmp(words[1], "warning") && count == 4
            && !strcasecmp(words[2], "time")
            && runtime_worldborder_seconds(words[3], &command.duration_ms)
            && command.duration_ms / 1000LL <= INT_MAX) {
        command.kind = RUNTIME_WORLDBORDER_WARNING_TIME;
        command.first = (double)(command.duration_ms / 1000LL);
    } else if (!strcasecmp(words[1], "warning") && count == 4
            && !strcasecmp(words[2], "distance")
            && runtime_worldborder_seconds(words[3], &command.duration_ms)
            && command.duration_ms / 1000LL <= INT_MAX) {
        command.kind = RUNTIME_WORLDBORDER_WARNING_DISTANCE;
        command.first = (double)(command.duration_ms / 1000LL);
    } else return 0;
    if (parsed) *parsed = command;
    return 1;
}

static int runtime_default_worldborder_get_output_is(const char *value) {
    char prefix[160];
    static const char suffix[] = "] \"}";
    int written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"commands.worldborder.get.success\","
        "\"with\":[\"60000000\"]}],\"text\":\"[");
    size_t prefix_length;
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

static int runtime_worldborder_translation_output_is(
        const char *value, const char *translation) {
    char prefix[160];
    static const char before_time[] = "}],\"text\":\"[";
    static const char suffix[] = "] \"}";
    size_t length, time_at;
    int written;
    if (!value || !translation) return 0;
    written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"%s\",\"with\":[",
        translation);
    if (written < 0 || written >= (int)sizeof prefix
            || strncmp(value, prefix, (size_t)written))
        return 0;
    length = strlen(value);
    if (length < 8u + sizeof suffix - 1u + sizeof before_time - 1u)
        return 0;
    time_at = length - (8u + sizeof suffix - 1u);
    if (strcmp(value + time_at + 8u, suffix)
            || time_at < sizeof before_time - 1u
            || memcmp(value + time_at - (sizeof before_time - 1u),
                      before_time, sizeof before_time - 1u))
        return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[time_at + index] != ':'
                : !isdigit((unsigned char)value[time_at + index]))
            return 0;
    return 1;
}

static int runtime_worldborder_output_is(
        const char *value, const RuntimeWorldBorderCommand *command) {
    char prefix[256];
    static const char suffix[] = "] \"}";
    const char *translation, *arguments;
    int written;
    size_t prefix_length;
    int kind = command ? command->kind : 0;
    if (kind == RUNTIME_WORLDBORDER_GET)
        return runtime_default_worldborder_get_output_is(value)
            || runtime_worldborder_translation_output_is(
                value, "commands.worldborder.get.success");
    if (kind == RUNTIME_WORLDBORDER_SET
            && command->duration_ms == 0 && command->first == 1000.0) {
        translation = "commands.worldborder.set.success";
        arguments = "\"1000.0\",\"60000000.0\"";
    } else if (kind == RUNTIME_WORLDBORDER_ADD
            && command->duration_ms == 0 && command->first == -100.0) {
        translation = "commands.worldborder.set.success";
        arguments = "\"59999900.0\",\"60000000.0\"";
    } else if (kind == RUNTIME_WORLDBORDER_CENTER
            && !command->first_relative && !command->second_relative
            && command->first == 12.5 && command->second == -7.5) {
        translation = "commands.worldborder.center.success";
        arguments = "\"12.5\",\"-7.5\"";
    } else if (kind == RUNTIME_WORLDBORDER_DAMAGE_BUFFER
            && command->first == 3.0) {
        translation = "commands.worldborder.damage.buffer.success";
        arguments = "\"3.0\",\"5.0\"";
    } else if (kind == RUNTIME_WORLDBORDER_DAMAGE_AMOUNT
            && command->first == 0.5) {
        translation = "commands.worldborder.damage.amount.success";
        arguments = "\"0.50\",\"0.20\"";
    } else if (kind == RUNTIME_WORLDBORDER_WARNING_TIME
            && command->first == 20.0) {
        translation = "commands.worldborder.warning.time.success";
        arguments = "\"20\",\"15\"";
    } else if (kind == RUNTIME_WORLDBORDER_WARNING_DISTANCE
            && command->first == 7.0) {
        translation = "commands.worldborder.warning.distance.success";
        arguments = "\"7\",\"5\"";
    } else if (kind == RUNTIME_WORLDBORDER_SET
            && command->duration_ms == 0 && command->first == 1.0) {
        translation = "commands.worldborder.set.success";
        arguments = "\"1.0\",\"60000000.0\"";
    } else {
        if (kind == RUNTIME_WORLDBORDER_SET
                || kind == RUNTIME_WORLDBORDER_ADD) {
            if (command->duration_ms > 0)
                return runtime_worldborder_translation_output_is(
                           value,
                           "commands.worldborder.setSlowly.grow.success")
                    || runtime_worldborder_translation_output_is(
                           value,
                           "commands.worldborder.setSlowly.shrink.success");
            translation = "commands.worldborder.set.success";
        } else if (kind == RUNTIME_WORLDBORDER_CENTER)
            translation = "commands.worldborder.center.success";
        else if (kind == RUNTIME_WORLDBORDER_DAMAGE_BUFFER)
            translation = "commands.worldborder.damage.buffer.success";
        else if (kind == RUNTIME_WORLDBORDER_DAMAGE_AMOUNT)
            translation = "commands.worldborder.damage.amount.success";
        else if (kind == RUNTIME_WORLDBORDER_WARNING_TIME)
            translation = "commands.worldborder.warning.time.success";
        else if (kind == RUNTIME_WORLDBORDER_WARNING_DISTANCE)
            translation = "commands.worldborder.warning.distance.success";
        else return 0;
        return runtime_worldborder_translation_output_is(value, translation);
    }
    written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"%s\",\"with\":[%s]}],"
        "\"text\":\"[", translation, arguments);
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

