static int runtime_player_uuid_string(
        const GmRuntime *r, char uuid[37]) {
    unsigned long long most, least;
    if (!r || !uuid) return 0;
    most = (unsigned long long)r->player_uuid_most;
    least = (unsigned long long)r->player_uuid_least;
    return snprintf(uuid, 37,
        "%08llx-%04llx-%04llx-%04llx-%012llx",
        most >> 32, (most >> 16) & 0xffffULL, most & 0xffffULL,
        least >> 48, least & 0xffffffffffffULL) == 36;
}

