typedef struct {
    int kind;
    double x, y, z;
    float yaw, pitch;
} RuntimeTeleportCommand;

static int runtime_teleport_coordinate(
        const char *text, double base, int center_block,
        double minimum, double maximum, double *result) {
    char *end;
    const char *number;
    double amount;
    int relative;
    if (!text || !text[0] || !result) return 0;
    relative = text[0] == '~';
    number = text + relative;
    if (relative && !number[0]) amount = 0.0;
    else {
        errno = 0;
        amount = strtod(number, &end);
        if (errno == ERANGE || end == number || *end || !isfinite(amount))
            return 0;
    }
    if (!relative && center_block && !strchr(number, '.')) amount += 0.5;
    *result = relative ? base + amount : amount;
    return *result >= minimum && *result <= maximum;
}

static float runtime_wrap_degrees(float value) {
    value = fmodf(value, 360.0F);
    if (value >= 180.0F) value -= 360.0F;
    if (value < -180.0F) value += 360.0F;
    return value;
}

static int runtime_parse_single_player_teleport_command(
        const GmRuntime *r, const char *value,
        int source_x, int source_y, int source_z,
        RuntimeTeleportCommand *parsed) {
    char buffer[192], *words[8], *save = NULL, *word;
    RuntimeTeleportCommand command = {0};
    double base_x, base_y, base_z, yaw, pitch;
    int count = 0;
    if (!r || !value || strlen(value) >= sizeof buffer) return 0;
    memcpy(buffer, value, strlen(value) + 1u);
    for (word = strtok_r(buffer, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= 8) return 0;
        words[count++] = word;
    }
    if ((count != 5 && count != 7) || strcmp(words[1], "@p")) return 0;
    if (!strcasecmp(words[0], "tp")) command.kind = 1;
    else if (!strcasecmp(words[0], "teleport")) command.kind = 2;
    else return 0;
    base_x = command.kind == 1
        ? r->server_player.ent.posX + r->ox : source_x + 0.5;
    base_y = command.kind == 1
        ? r->server_player.ent.posY : source_y + 0.5;
    base_z = command.kind == 1
        ? r->server_player.ent.posZ + r->oz : source_z + 0.5;
    if (!runtime_teleport_coordinate(
                words[2], base_x, 1, -30000000.0, 30000000.0, &command.x)
            || !runtime_teleport_coordinate(
                words[3], base_y, 0, -4096.0, 4096.0, &command.y)
            || !runtime_teleport_coordinate(
                words[4], base_z, 1, -30000000.0, 30000000.0, &command.z))
        return 0;
    yaw = r->server_player.yaw;
    pitch = r->server_player.pitch;
    if (count == 7) {
        if (!runtime_teleport_coordinate(
                    words[5], yaw, 0, -DBL_MAX, DBL_MAX, &yaw)
                || !runtime_teleport_coordinate(
                    words[6], pitch, 0, -DBL_MAX, DBL_MAX, &pitch))
            return 0;
        if (words[5][0] != '~') yaw = runtime_wrap_degrees((float)yaw);
        if (words[6][0] != '~') pitch = runtime_wrap_degrees((float)pitch);
    }
    command.yaw = (float)yaw;
    command.pitch = (float)pitch;
    if (parsed) *parsed = command;
    return 1;
}

static int runtime_format_command_double(
        char *output, size_t capacity, double value) {
    int written;
    if (!output || !capacity || !isfinite(value)) return 0;
    written = snprintf(output, capacity, "%.15g", value);
    if (written < 0 || (size_t)written >= capacity) return 0;
    if (!strchr(output, '.') && !strchr(output, 'e') && !strchr(output, 'E')) {
        if ((size_t)written + 2u >= capacity) return 0;
        output[written++] = '.';
        output[written++] = '0';
        output[written] = '\0';
    }
    return 1;
}

static int runtime_single_player_teleport_output_is(
        const char *value, const char *player_name,
        const RuntimeTeleportCommand *command) {
    char prefix[224];
    char x[48], y[48], z[48];
    static const char suffix[] = "] \"}";
    int written;
    size_t prefix_length;
    if (!player_name || !command
            || !runtime_format_command_double(x, sizeof x, command->x)
            || !runtime_format_command_double(y, sizeof y, command->y)
            || !runtime_format_command_double(z, sizeof z, command->z))
        return 0;
    written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"commands.%s.success.coordinates\","
        "\"with\":[\"%s\",\"%s\",\"%s\",\"%s\"]}],"
        "\"text\":\"[", command->kind == 1 ? "tp" : "teleport",
        player_name, x, y, z);
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

