static int runtime_effect_output_prefix(
        char *prefix, size_t capacity, const char *player_name,
        const RuntimeEffectCommand *command) {
    if (!prefix || !capacity || !player_name || !command) return -1;
    if (command->kind == 3)
        return snprintf(prefix, capacity,
            "{\"extra\":[{\"translate\":"
            "\"commands.effect.success.removed.all\","
            "\"with\":[\"%s\"]}],\"text\":\"[", player_name);
    if (command->kind == 2)
        return snprintf(prefix, capacity,
            "{\"extra\":[{\"translate\":"
            "\"commands.effect.success.removed\",\"with\":["
            "{\"translate\":\"%s\"},\"%s\"]}],\"text\":\"[",
            runtime_potion_specs[command->id].translation, player_name);
    return snprintf(prefix, capacity,
        "{\"extra\":[{\"translate\":\"commands.effect.success\","
        "\"with\":[{\"translate\":\"%s\"},"
        "\"%d\",\"%d\",\"%s\",\"%d\"]}],\"text\":\"[",
        runtime_potion_specs[command->id].translation,
        command->id, command->amplifier, player_name, command->seconds);
}

