static int runtime_seed_output_is(const char *value) {
    static const char prefix[] =
        "{\"extra\":[{\"translate\":\"commands.seed.success\","
        "\"with\":[\"";
    static const char suffix[] = "] \"}";
    const char *number;
    char *end;
    if (!value || strncmp(value, prefix, sizeof prefix - 1u)) return 0;
    number = value + sizeof prefix - 1u;
    errno = 0;
    (void)strtoll(number, &end, 10);
    if (errno || end == number || strncmp(end, "\"]}],\"text\":\"[", 15))
        return 0;
    end += 15;
    if (strlen(end) != 8u + sizeof suffix - 1u
            || strcmp(end + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? end[index] != ':'
                : !isdigit((unsigned char)end[index]))
            return 0;
    return 1;
}

