static int runtime_registered_block_id(const char *name) {
    static const GmItemNameId exceptions[] = {
        {"minecraft:flowing_water", 8}, {"minecraft:water", 9},
        {"minecraft:flowing_lava", 10}, {"minecraft:lava", 11},
        {"minecraft:bed", 26}, {"minecraft:piston_head", 34},
        {"minecraft:piston_extension", 36},
        {"minecraft:double_stone_slab", 43}, {"minecraft:fire", 51},
        {"minecraft:redstone_wire", 55}, {"minecraft:wheat", 59},
        {"minecraft:lit_furnace", 62}, {"minecraft:standing_sign", 63},
        {"minecraft:wooden_door", 64}, {"minecraft:wall_sign", 68},
        {"minecraft:iron_door", 71}, {"minecraft:lit_redstone_ore", 74},
        {"minecraft:unlit_redstone_torch", 75}, {"minecraft:reeds", 83},
        {"minecraft:portal", 90}, {"minecraft:cake", 92},
        {"minecraft:unpowered_repeater", 93},
        {"minecraft:powered_repeater", 94},
        {"minecraft:pumpkin_stem", 104}, {"minecraft:melon_stem", 105},
        {"minecraft:nether_wart", 115}, {"minecraft:brewing_stand", 117},
        {"minecraft:cauldron", 118}, {"minecraft:end_portal", 119},
        {"minecraft:lit_redstone_lamp", 124},
        {"minecraft:double_wooden_slab", 125}, {"minecraft:cocoa", 127},
        {"minecraft:tripwire", 132}, {"minecraft:flower_pot", 140},
        {"minecraft:carrots", 141}, {"minecraft:potatoes", 142},
        {"minecraft:skull", 144}, {"minecraft:unpowered_comparator", 149},
        {"minecraft:powered_comparator", 150},
        {"minecraft:standing_banner", 176}, {"minecraft:wall_banner", 177},
        {"minecraft:daylight_detector_inverted", 178},
        {"minecraft:double_stone_slab2", 181},
        {"minecraft:spruce_door", 193}, {"minecraft:birch_door", 194},
        {"minecraft:jungle_door", 195}, {"minecraft:acacia_door", 196},
        {"minecraft:dark_oak_door", 197},
        {"minecraft:purpur_double_slab", 204}, {"minecraft:beetroots", 207},
        {"minecraft:end_gateway", 209}, {"minecraft:frosted_ice", 212}
    };
    int id;
    if (!name) return -1;
    for (size_t index = 0;
            index < sizeof exceptions / sizeof exceptions[0]; ++index)
        if (!strcmp(name, exceptions[index].name))
            return exceptions[index].id;
    id = gm_item_id_from_name_1_11_2(name);
    if (id == 0 && strcmp(name, "minecraft:air")) return -1;
    return id >= 0 && (id <= 234 || id == 255) ? id : -1;
}

static int runtime_parse_block_coordinate(
        const char *text, int origin, int *result) {
    int relative = text && text[0] == '~';
    int value = 0;
    if (!text || !result) return 0;
    if (relative && !text[1]) {
        *result = origin;
        return 1;
    }
    if (!runtime_parse_signed_int(text + relative, &value)) return 0;
    if ((value > 0 && origin > INT_MAX - value)
            || (value < 0 && origin < INT_MIN - value))
        return 0;
    *result = relative ? origin + value : value;
    return 1;
}

static int runtime_parse_setblock_command(
        const char *value, int origin_x, int origin_y, int origin_z,
        RuntimeSetBlockCommand *parsed) {
    char copy[128], *words[8], *save = NULL, *word;
    int count = 0;
    if (!value || !parsed || strlen(value) >= sizeof copy) return 0;
    memcpy(copy, value, strlen(value) + 1u);
    for (word = strtok_r(copy, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= (int)(sizeof words / sizeof words[0])) return 0;
        words[count++] = word;
    }
    if (count < 5 || count > 7 || strcasecmp(words[0], "setblock")
            || !runtime_parse_block_coordinate(words[1], origin_x, &parsed->x)
            || !runtime_parse_block_coordinate(words[2], origin_y, &parsed->y)
            || !runtime_parse_block_coordinate(words[3], origin_z, &parsed->z))
        return 0;
    parsed->block = runtime_registered_block_id(words[4]);
    if (parsed->block < 0 || parsed->y < 0 || parsed->y > 255) return 0;
    parsed->meta = 0;
    parsed->mode = 0;
    if (count >= 6
            && (!runtime_parse_nonnegative_int(words[5], &parsed->meta)
                || parsed->meta > 15))
        return 0;
    if (count < 7 || !strcmp(words[6], "replace")) return 1;
    if (!strcmp(words[6], "keep")) {
        parsed->mode = 1;
        return 1;
    }
    if (!strcmp(words[6], "destroy")) {
        parsed->mode = 2;
        return 1;
    }
    /* Tile NBT requires its own atomic construction semantics. */
    return 0;
}

static int runtime_parse_single_player_execute_setblock_command(
        const GmRuntime *r, const char *value,
        RuntimeSetBlockCommand *parsed) {
    static const char command[] =
        "execute @p ~ ~ ~ setblock ~6 ~ ~ minecraft:gold_block 0 replace";
    if (!r || !value || !parsed || strcasecmp(value, command)) return 0;
    return runtime_parse_setblock_command(
        value + sizeof "execute @p ~ ~ ~ " - 1u,
        (int)floor(r->player.ent.posX),
        (int)floor(r->player.ent.posY),
        (int)floor(r->player.ent.posZ), parsed);
}

static int runtime_parse_testforblock_command(
        const char *value, int origin_x, int origin_y, int origin_z,
        RuntimeTestForBlockCommand *parsed) {
    char copy[128], *words[7], *save = NULL, *word;
    int count = 0;
    if (!value || !parsed || strlen(value) >= sizeof copy) return 0;
    memcpy(copy, value, strlen(value) + 1u);
    for (word = strtok_r(copy, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= (int)(sizeof words / sizeof words[0])) return 0;
        words[count++] = word;
    }
    if ((count != 5 && count != 6)
            || strcasecmp(words[0], "testforblock")
            || !runtime_parse_block_coordinate(words[1], origin_x, &parsed->x)
            || !runtime_parse_block_coordinate(words[2], origin_y, &parsed->y)
            || !runtime_parse_block_coordinate(words[3], origin_z, &parsed->z))
        return 0;
    parsed->block = runtime_registered_block_id(words[4]);
    if (parsed->block < 0 || parsed->y < 0 || parsed->y > 255) return 0;
    parsed->meta = -1;
    if (count == 6 && strcmp(words[5], "*")
            && (!runtime_parse_nonnegative_int(words[5], &parsed->meta)
                || parsed->meta > 15))
        return 0;
    return 1;
}

static int runtime_testforblock_output_is(
        const char *value, const RuntimeTestForBlockCommand *command) {
    char prefix[192];
    static const char suffix[] = "] \"}";
    int written;
    size_t prefix_length;
    if (!command) return 0;
    written = snprintf(prefix, sizeof prefix,
        "{\"extra\":[{\"translate\":\"commands.testforblock.success\","
        "\"with\":[\"%d\",\"%d\",\"%d\"]}],\"text\":\"[",
        command->x, command->y, command->z);
    if (written < 0 || written >= (int)sizeof prefix) return 0;
    prefix_length = (size_t)written;
    if (!value || strncmp(value, prefix, prefix_length)
            || strlen(value) != prefix_length + 8u + sizeof suffix - 1u
            || strcmp(value + prefix_length + 8u, suffix)) return 0;
    for (size_t index = 0; index < 8u; ++index)
        if ((index == 2u || index == 5u)
                ? value[prefix_length + index] != ':'
                : !isdigit((unsigned char)value[prefix_length + index]))
            return 0;
    return 1;
}

static int runtime_parse_compare_command(
        const char *value, int origin_x, int origin_y, int origin_z,
        RuntimeCompareCommand *parsed) {
    char copy[160], *words[12], *save = NULL, *word;
    int count = 0, coordinates[9];
    if (!value || !parsed || strlen(value) >= sizeof copy) return 0;
    memcpy(copy, value, strlen(value) + 1u);
    for (word = strtok_r(copy, " ", &save); word;
            word = strtok_r(NULL, " ", &save)) {
        if (count >= (int)(sizeof words / sizeof words[0])) return 0;
        words[count++] = word;
    }
    if ((count != 10 && count != 11)
            || strcasecmp(words[0], "testforblocks")) return 0;
    for (int index = 0; index < 9; ++index) {
        int origin = index % 3 == 0 ? origin_x
            : index % 3 == 1 ? origin_y : origin_z;
        if (!runtime_parse_block_coordinate(
                words[index + 1], origin, &coordinates[index])) return 0;
    }
    parsed->x0 = coordinates[0]; parsed->y0 = coordinates[1];
    parsed->z0 = coordinates[2]; parsed->x1 = coordinates[3];
    parsed->y1 = coordinates[4]; parsed->z1 = coordinates[5];
    parsed->dx = coordinates[6]; parsed->dy = coordinates[7];
    parsed->dz = coordinates[8];
    parsed->masked = count == 11 && !strcmp(words[10], "masked");
    if (count == 11 && !parsed->masked && strcmp(words[10], "all")) return 0;
    if (parsed->x0 > parsed->x1) {
        int hold = parsed->x0; parsed->x0 = parsed->x1; parsed->x1 = hold;
    }
    if (parsed->y0 > parsed->y1) {
        int hold = parsed->y0; parsed->y0 = parsed->y1; parsed->y1 = hold;
    }
    if (parsed->z0 > parsed->z1) {
        int hold = parsed->z0; parsed->z0 = parsed->z1; parsed->z1 = hold;
    }
    long long cells = (long long)(parsed->x1 - parsed->x0 + 1)
        * (parsed->y1 - parsed->y0 + 1)
        * (parsed->z1 - parsed->z0 + 1);
    return parsed->y0 >= 0 && parsed->y1 < 256
        && parsed->dy >= 0 && parsed->dy + parsed->y1 - parsed->y0 < 256
        && cells <= 524288;
}

