int gm_runtime_structure_load(
        GmRuntime *r, int dimension, int x, int y, int z,
        int require_matching_size) {
    GmRuntimeStructureBlock *controller =
        runtime_structure_block_at_mut(r, dimension, x, y, z);
    GmRuntimeStructureTemplate *structure;
    JavaRandom random = {0};
    float integrity;
    int use_integrity;
    int base_x, base_y, base_z;
    int mirror, rotation;
    if (!controller || dimension != r->dimension
            || controller->mode != GM_STRUCTURE_MODE_LOAD
            || controller->name[0] == '\0')
        return 0;
    structure = runtime_structure_template_find(r, controller->name);
    if (!structure) return 0;
    if (structure->author[0] != '\0')
        runtime_structure_copy_string(
            controller->author, sizeof controller->author,
            structure->author, 0);
    if (controller->size_x != structure->size_x
            || controller->size_y != structure->size_y
            || controller->size_z != structure->size_z) {
        controller->size_x = structure->size_x;
        controller->size_y = structure->size_y;
        controller->size_z = structure->size_z;
        if (require_matching_size) return 0;
    }
    if (structure->size_x < 1 || structure->size_y < 1
            || structure->size_z < 1)
        return 1;
    if (!controller->ignore_entities) {
        int living_needed = 0, xp_needed = 0, items_needed = 0;
        int tnt_needed = 0, falling_needed = 0, crystals_needed = 0;
        int minecarts_needed = 0;
        for (int index = 0; index < structure->entity_count; ++index) {
            if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_LIVING
                    || structure->entities[index].kind
                        == GM_TEMPLATE_ENTITY_BOAT)
                ++living_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_XP)
                ++xp_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_ITEM)
                ++items_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_PRIMED_TNT)
                ++tnt_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_FALLING_BLOCK)
                ++falling_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_END_CRYSTAL)
                ++crystals_needed;
            else if (structure->entities[index].kind
                    == GM_TEMPLATE_ENTITY_MINECART)
                ++minecarts_needed;
        }
        if (!gm_mobs_living_spawn_reserve(&r->mobs, living_needed)
                || !gm_live_reserve_plain_spawns(
                    &r->entities, items_needed)
                || !runtime_primed_tnt_reserve(
                    r, r->primed_tnt_count + tnt_needed)
                || !runtime_falling_blocks_reserve(
                    r, r->falling_block_count + falling_needed)
                || !runtime_end_crystals_reserve(
                    r, r->end_crystal_count + crystals_needed)
                || !runtime_minecarts_reserve(
                    r, r->minecart_count + minecarts_needed)
                || structure->entity_count
                    > GM_RUNTIME_COLD_STORE_MAX
                        - r->loaded_entity_order_count
                || r->next_entity_id <= 0
                || structure->entity_count > INT_MAX - r->next_entity_id)
            return 0;
    }
    base_x = x + controller->pos_x;
    base_y = y + controller->pos_y;
    base_z = z + controller->pos_z;
    mirror = controller->mirror;
    rotation = controller->rotation;
    integrity = controller->integrity;
    use_integrity = integrity < 1.0f;
    if (use_integrity) {
        long long seed = controller->seed;
        if (integrity < 0.0f) integrity = 0.0f;
        if (integrity > 1.0f) integrity = 1.0f;
        if (seed == 0) {
            struct timespec now;
            if (clock_gettime(CLOCK_REALTIME, &now) == 0)
                seed = (long long)now.tv_sec * 1000LL
                    + (long long)now.tv_nsec / 1000000LL;
            else
                seed = (long long)time(NULL) * 1000LL;
        }
        jrand_set(&random, seed);
    }
    /* Template stores blocks in three stable passes: full blocks, tile
     * entities, then non-full blocks. The category table was recorded from
     * IBlockState.isFullBlock/isFullCube and Block.hasTileEntity. */
    for (int category = 0; category < 3; ++category)
        for (int rz = 0; rz < structure->size_z; ++rz)
            for (int ry = 0; ry < structure->size_y; ++ry)
                for (int rx = 0; rx < structure->size_x; ++rx) {
                    int index = runtime_structure_index(
                        structure->size_x, structure->size_y,
                        rx, ry, rz);
                    const GmRuntimeStructureTile *tile;
                    uint16_t state;
                    int id, meta, transformed_meta, tx, ty, tz;
                    if (!structure->present[index]) continue;
                    state = structure->states[index];
                    id = state >> 4;
                    meta = state & 15;
                    if (id < 256
                            && GM_STRUCTURE_BLOCK_CATEGORY[id * 16 + meta]
                                != category)
                        continue;
                    if (id >= 256 && category != 2) continue;
                    if (use_integrity && jrand_float(&random) > integrity)
                        continue;
                    runtime_structure_transform_position(
                        mirror, rotation, rx, ry, rz, &tx, &ty, &tz);
                    tx += base_x;
                    ty += base_y;
                    tz += base_z;
                    transformed_meta = runtime_structure_transform_meta(
                        id, meta, mirror, rotation);
                    tile = runtime_structure_tile_for_cell(structure, index);
                    if (tile
                            && !runtime_set_block_flags(
                                r, tx, ty, tz, 166, 0, 4))
                        continue;
                    if (!runtime_set_block_flags(
                            r, tx, ty, tz, id, transformed_meta, 2))
                        continue;
                    (void)runtime_structure_restore_tile(
                        r, tile, id, transformed_meta, tx, ty, tz,
                        mirror, rotation);
                }
    /* Template's second pass is intentionally independent of the integrity
     * processor. It notifies every stored position with the original block,
     * in stable BlockInfo order, and explicitly does not update observers. */
    for (int category = 0; category < 3; ++category)
        for (int rz = 0; rz < structure->size_z; ++rz)
            for (int ry = 0; ry < structure->size_y; ++ry)
                for (int rx = 0; rx < structure->size_x; ++rx) {
                    int index = runtime_structure_index(
                        structure->size_x, structure->size_y,
                        rx, ry, rz);
                    uint16_t state;
                    int id, meta, tx, ty, tz;
                    if (!structure->present[index]) continue;
                    state = structure->states[index];
                    id = state >> 4;
                    meta = state & 15;
                    if (id < 256
                            && GM_STRUCTURE_BLOCK_CATEGORY[id * 16 + meta]
                                != category)
                        continue;
                    if (id >= 256 && category != 2) continue;
                    runtime_structure_transform_position(
                        mirror, rotation, rx, ry, rz, &tx, &ty, &tz);
                    runtime_redstone_notify_neighbors_from(
                        r, base_x + tx, base_y + ty, base_z + tz, id);
                }
    if (!controller->ignore_entities) {
        for (int index = 0; index < structure->entity_count; ++index) {
            GmMobTemplateEntity entity = structure->entities[index];
            JavaRandom entity_random;
            int64_t uuid_most, uuid_least;
            int eid = r->next_entity_id++;
            runtime_structure_transform_entity_position(
                mirror, rotation, entity.x, entity.y, entity.z,
                &entity.x, &entity.y, &entity.z);
            entity.x += (double)base_x;
            entity.y += (double)base_y;
            entity.z += (double)base_z;
            entity.yaw = runtime_structure_transform_entity_yaw(
                entity.yaw, mirror, rotation);
            runtime_next_server_uuid(r, &uuid_most, &uuid_least);
            jrand_set(&entity_random, runtime_java_random_seed_next_long(
                &r->entity_seed_generator_seed48));
            /* EntityLivingBase's constructor initializes two animation
             * offsets and a yaw from three Math.random doubles. All three
             * values are transient or overwritten by NBT, but the shared
             * cursor remains observable by later constructors. */
            if (entity.kind == GM_TEMPLATE_ENTITY_LIVING)
                for (int draw = 0; draw < 3; ++draw)
                    (void)runtime_math_random_next_double(r);
            if (entity.kind == GM_TEMPLATE_ENTITY_ITEM) {
                if (!runtime_structure_spawn_item(
                        r, &entity, eid, uuid_most, uuid_least,
                        entity_random.seed))
                    return 0;
                continue;
            }
            if (entity.kind == GM_TEMPLATE_ENTITY_PRIMED_TNT) {
                if (!runtime_structure_spawn_primed_tnt(
                        r, &entity, eid, uuid_most, uuid_least,
                        entity_random.seed))
                    return 0;
                continue;
            }
            if (entity.kind == GM_TEMPLATE_ENTITY_FALLING_BLOCK) {
                if (!runtime_structure_spawn_falling_block(
                        r, &entity, eid, uuid_most, uuid_least,
                        entity_random.seed))
                    return 0;
                continue;
            }
            if (entity.kind == GM_TEMPLATE_ENTITY_END_CRYSTAL) {
                if (!runtime_structure_spawn_end_crystal(
                        r, &entity, eid, uuid_most, uuid_least,
                        &entity_random))
                    return 0;
                continue;
            }
            if (entity.kind == GM_TEMPLATE_ENTITY_MINECART) {
                if (!runtime_structure_spawn_minecart(
                        r, &entity, eid, uuid_most, uuid_least,
                        entity_random.seed))
                    return 0;
                continue;
            }
            r->mobs.active_dimension = dimension;
            if (gm_mobs_template_entity_spawn(
                    &r->mobs, &entity, eid) != eid)
                return 0;
            if (!gm_mobs_set_entity_uuid(
                    &r->mobs, eid, uuid_most, uuid_least)
                    || ((entity.kind == GM_TEMPLATE_ENTITY_LIVING
                            || entity.kind == GM_TEMPLATE_ENTITY_BOAT)
                        && !gm_mobs_set_entity_random_state(
                            &r->mobs, eid, entity_random.seed, 0, 0.0))
                    || !runtime_loaded_entity_order_append(r, eid))
                return 0;
            r->controlled_mobs_enabled = 1;
            if (entity.kind == GM_TEMPLATE_ENTITY_LIVING
                    && !entity.no_ai)
                r->restored_active_mobs_enabled = 1;
        }
    }
    return 1;
}

int gm_runtime_structure_unload(
        GmRuntime *r, int dimension, int x, int y, int z) {
    GmRuntimeStructureBlock *controller =
        runtime_structure_block_at_mut(r, dimension, x, y, z);
    GmRuntimeStructureTemplate *structure;
    if (!controller || controller->name[0] == '\0') return 0;
    structure = runtime_structure_template_find(r, controller->name);
    if (!structure) return 0;
    memset(structure, 0, sizeof *structure);
    return 1;
}

static int runtime_structure_trigger(
        GmRuntime *r, GmRuntimeStructureBlock *structure) {
    int dimension, x, y, z, mode;
    if (!r || !structure) return 0;
    dimension = structure->dimension;
    x = structure->wx;
    y = structure->wy;
    z = structure->wz;
    mode = structure->mode;
    if (mode == GM_STRUCTURE_MODE_SAVE)
        return gm_runtime_structure_save(r, dimension, x, y, z);
    if (mode == GM_STRUCTURE_MODE_LOAD)
        return gm_runtime_structure_load(r, dimension, x, y, z, 0);
    if (mode == GM_STRUCTURE_MODE_CORNER)
        return gm_runtime_structure_unload(r, dimension, x, y, z);
    return 1;
}

int gm_runtime_flower_pot_count(const GmRuntime *r) {
    int count = 0;
    if (!r || !r->flower_pots) return 0;
    for (int i = 0; i < r->flower_pots_cap; ++i) {
        const GmRuntimeFlowerPot *pot = &r->flower_pots[i];
        if (pot->active
                && pot->dimension == r->dimension
                && gm_world_block(
                    r->world, pot->wx, pot->wy, pot->wz) == 140)
            count++;
    }
    return count;
}

int gm_runtime_flower_pot_get(
        const GmRuntime *r, int index, GmRuntimeFlowerPot *out) {
    int at = 0;
    if (!r || !r->flower_pots || !out || index < 0)
        return 0;
    for (int i = 0; i < r->flower_pots_cap; ++i) {
        const GmRuntimeFlowerPot *pot = &r->flower_pots[i];
        if (!pot->active
                || pot->dimension != r->dimension
                || gm_world_block(
                    r->world, pot->wx, pot->wy, pot->wz) != 140)
            continue;
        if (at++ == index) {
            *out = *pot;
            return 1;
        }
    }
    return 0;
}

int gm_runtime_flower_pot_set(
        GmRuntime *r, int dimension, int x, int y, int z,
        int item, int meta) {
    int index = -1;
    int free_slot = -1;
    if (!r || !r->world || dimension != r->dimension
            || y < 0 || y > 255
            || gm_world_block(r->world, x, y, z) != 140
            || item < 0 || item > 4095
            || meta < 0 || meta > 32767
            || (item == 0 && meta != 0))
        return 0;
    for (int i = 0; i < r->flower_pots_cap; ++i) {
        GmRuntimeFlowerPot *candidate = &r->flower_pots[i];
        if (candidate->active
                && candidate->dimension == dimension
                && candidate->wx == x && candidate->wy == y
                && candidate->wz == z) {
            index = i;
            break;
        }
        if (!candidate->active && free_slot < 0)
            free_slot = i;
    }
    if (index < 0) index = free_slot;
    if (index < 0) {
        int old_cap = r->flower_pots_cap;
        int new_cap = old_cap > 0
            ? old_cap * 2 : GM_RUNTIME_FLOWER_POTS_INITIAL;
        GmRuntimeFlowerPot *grown;
        if (new_cap > GM_RUNTIME_COLD_STORE_MAX)
            new_cap = GM_RUNTIME_COLD_STORE_MAX;
        if (new_cap <= old_cap)
            return 0;
        grown = (GmRuntimeFlowerPot *)realloc(
            r->flower_pots, (size_t)new_cap * sizeof *grown);
        if (!grown) return 0;
        memset(grown + old_cap, 0,
               (size_t)(new_cap - old_cap) * sizeof *grown);
        r->flower_pots = grown;
        r->flower_pots_cap = new_cap;
        index = old_cap;
    }
    GmRuntimeFlowerPot *pot = &r->flower_pots[index];
    *pot = (GmRuntimeFlowerPot){
        .active = 1,
        .dimension = dimension,
        .wx = x,
        .wy = y,
        .wz = z,
        .item = item,
        .meta = meta,
    };
    return 1;
}

static void runtime_flower_pot_remove(
        GmRuntime *r, int dimension, int x, int y, int z) {
    if (!r || !r->flower_pots) return;
    for (int i = 0; i < r->flower_pots_cap; ++i) {
        GmRuntimeFlowerPot *pot = &r->flower_pots[i];
        if (pot->active && pot->dimension == dimension
                && pot->wx == x && pot->wy == y && pot->wz == z) {
            memset(pot, 0, sizeof *pot);
            return;
        }
    }
}

