int gm_runtime_projectile_views(const GmRuntime *r, GmEntityView *out, int max) {
    if (!r || !out || max <= 0) return 0;
    int n = 0;
    for (int i = 0; i < r->projectiles_cap && n < max; ++i) {
        const GmRuntimeProjectile *p = &r->projectiles[i];
        if (!p->active) continue;
        GmEntityView v; memset(&v, 0, sizeof v);
        v.x = (float)p->x; v.y = (float)p->y; v.z = (float)p->z;
        v.health = 1.0f;
        v.ent_id = p->eid;
        if (p->type == 1 || p->type == 2) {
            /* bow arrows: RenderArrow model, oriented from velocity like
             * vanilla EntityArrow (yaw atan2(vx,vz), pitch atan2(vy,horiz)) */
            v.type = 29; /* ER_TYPE_ARROW */
            double h = sqrt(p->vx * p->vx + p->vz * p->vz);
            v.yaw   = (float)(atan2(p->vx, p->vz) * 180.0 / MC_PI);
            v.pitch = (float)(atan2(p->vy, h) * 180.0 / MC_PI);
        } else if (p->type == 3 || p->type == 5) {
            /* Fireballs use the fire_charge particle icon; the large ghast
             * shot shares this billboard path until scale is carried in views.
             * EntitySmallFireball uses RenderFireball scale 0.5.
             * particle icon. gm_items_emit_billboard selects that exact path
             * from item id 385. Live shots are isFireballFiery (setFire each
             * tick) so flags bit 0 enables renderEntityOnFire layers. */
            v.type = GM_VIEW_BILLBOARD; v.item_id = 385;
            v.flags = 1; /* burn / isBurning */
            if (p->type == 5) v.item_meta = 2; /* large width 1.0 fire overlay */
        } else if (p->type == 4) {
            v.type = GM_VIEW_BILLBOARD; v.item_id = 381; /* eye of ender */
        } else if (p->type == 10) {
            v.type = GM_VIEW_WITHER_SKULL;
            v.ent_id = p->eid;
            v.yaw = p->yaw;
            v.pitch = p->pitch;
            v.ticks_existed = p->age;
            v.wither_skull_invulnerable = p->wither_invulnerable;
        } else if (p->type == 11) {
            v.type = 73; /* ER_TYPE_LLAMA_SPIT */
            v.yaw = p->yaw;
            v.pitch = p->pitch;
            v.ticks_existed = p->age;
        } else if (p->type == 6) {
            v.type = GM_VIEW_BILLBOARD;
            v.item_id = p->potion_item;
            v.item_meta = p->potion_type;
        } else if ((p->type >= 7 && p->type <= 9)
                || p->type == 12) {
            v.type = GM_VIEW_BILLBOARD;
            v.item_id = p->potion_item;
        } else {
            v.type = 20; /* unknown: legacy marker box */
        }
        out[n++] = v;
    }
    for (int i = 0; i < r->fireworks_cap && n < max; ++i) {
        const GmRuntimeFirework *rocket = &r->fireworks[i];
        GmEntityView v;
        if (!rocket->active || rocket->dimension != r->dimension
                || rocket->attached_player)
            continue;
        memset(&v, 0, sizeof v);
        v.type = GM_VIEW_BILLBOARD;
        v.item_id = 401;
        v.ent_id = rocket->eid;
        v.x = (float)rocket->x;
        v.y = (float)rocket->y;
        v.z = (float)rocket->z;
        v.yaw = rocket->yaw;
        v.pitch = rocket->pitch;
        v.health = 1.0F;
        out[n++] = v;
    }
    if (r->fish_hook.active && r->fish_hook.dimension == r->dimension
            && n < max) {
        GmEntityView v;
        memset(&v, 0, sizeof v);
        /* Synthetic atlas id 9004 is RenderFish's exact particle-atlas cell.
         * It shares the camera-facing half-block quad transform used here. */
        v.type = GM_VIEW_BILLBOARD;
        v.item_id = 9004;
        v.ent_id = r->fish_hook.eid;
        v.x = (float)r->fish_hook.x;
        v.y = (float)r->fish_hook.y;
        v.z = (float)r->fish_hook.z;
        v.health = 1.0F;
        out[n++] = v;
    }
    for (int i = 0; i < r->minecarts_cap && n < max; ++i) {
        const GmRuntimeMinecart *cart = &r->minecarts[i];
        GmEntityView v;
        if (!cart->active || cart->dimension != r->dimension) continue;
        memset(&v, 0, sizeof v);
        switch (cart->kind) {
            case GM_MINECART_CHEST:   v.type = GM_VIEW_MINECART_CHEST; break;
            case GM_MINECART_FURNACE: v.type = GM_VIEW_MINECART_FURNACE; break;
            case GM_MINECART_TNT:     v.type = GM_VIEW_MINECART_TNT; break;
            case GM_MINECART_SPAWNER: v.type = GM_VIEW_MINECART_SPAWNER; break;
            case GM_MINECART_HOPPER:  v.type = GM_VIEW_MINECART_HOPPER; break;
            case GM_MINECART_COMMAND: v.type = GM_VIEW_MINECART_COMMAND; break;
            default:                  v.type = GM_VIEW_MINECART_EMPTY; break;
        }
        v.ent_id = cart->eid;
        v.x = (float)cart->x;
        v.y = (float)cart->y;
        v.z = (float)cart->z;
        v.yaw = cart->yaw;
        v.pitch = cart->pitch;
        v.health = -1.0f;
        v.minecart_custom_display = cart->custom_display;
        v.minecart_display_block = cart->display_block;
        v.minecart_display_meta = cart->display_meta;
        v.minecart_display_offset = cart->display_offset;
        v.minecart_powered = cart->kind == GM_MINECART_FURNACE
            && cart->fuel > 0;
        v.minecart_tnt_fuse = cart->tnt_fuse;
        v.minecart_tnt_fuse_valid = 1;
        out[n++] = v;
    }
    return n;
}

int gm_runtime_wither_views(
        const GmRuntime *r, GmEntityView *out, int max) {
    if (!r || !out || max <= 0 || r->wither_count <= 0) return 0;
    int n = 0;
    for (int i = 0; i < r->withers_cap && n < max; ++i) {
        const GmRuntimeWither *wither = &r->withers[i];
        GmEntityView view;
        if (!wither->active || wither->dimension != r->dimension) continue;
        memset(&view, 0, sizeof view);
        view.type = GM_VIEW_WITHER;
        view.ent_id = wither->eid;
        view.x = (float)wither->x;
        view.y = (float)wither->y;
        view.z = (float)wither->z;
        view.yaw = wither->render_yaw_offset;
        view.head_yaw = wither->rotation_yaw_head;
        view.pitch = wither->pitch;
        view.health = wither->health;
        view.hurt_time = wither->hurt_time;
        view.death_time = wither->death_time;
        view.tape_pose = 1;
        view.ticks_existed = wither->ticks_existed;
        view.wither_invul_time = wither->invul_time;
        for (int side = 0; side < 2; ++side) {
            view.wither_head_yaw[side] = wither->head_y_rotation[side];
            view.wither_head_pitch[side] = wither->head_x_rotation[side];
        }
        out[n++] = view;
    }
    return n;
}

