int gm_runtime_craft(GmRuntime *r, int grid_width, const int inv_slots[9]) {
    if (!r || (grid_width != 2 && grid_width != 3)) return 0;
    if (grid_width == 3 && r->container != 1) return 0;
    CRStack grid[9];
    ICStack actual[9];
    int use[ISR_MAIN_SLOTS];
    memset(use, 0, sizeof use);
    for (int i = 0; i < 9; ++i) {
        grid[i] = crf_empty();
        actual[i] = ic_empty();
        int slot = inv_slots[i];
        if (slot < 0) continue;
        if (slot >= ISR_MAIN_SLOTS) return 0;
        if (grid_width == 2 && (i % 3 >= 2 || i / 3 >= 2)) return 0;
        ICStack s = isr_get_stack(&r->player.inv, slot);
        if (isr_is_empty(&s)) return 0;
        use[slot]++;
        if (use[slot] > s.count) return 0;
        grid[i] = crf_mk(s.item, 1, s.meta);
        actual[i] = s;
        actual[i].count = 1;
    }
    GmCraftSpecial special;
    int special_match = gm_crafting_special_match(r, actual, &special);
    if (special_match < 0) return 0;
    CRRecipe recipes[CRF_NRECIPES];
    CRStack result = crf_empty();
    if (!special_match) {
        int nr = crf_build(recipes);
        result = crf_findMatching(recipes, nr, grid);
        if (crf_isEmpty(result) || result.item == (i32)0xffffffff) return 0;
    }
    IsrInv next = r->player.inv;
    ICStack remainders[9];
    int remainder_count = 0;
    for (int i = 0; i < 9; ++i) {
        if (cc_is_empty(&actual[i])) continue;
        ICStack remainder = special_match
            ? special.remainder[i]
            : ic_crafting_container_item(&actual[i]);
        if (!isr_is_empty(&remainder))
            remainders[remainder_count++] = remainder;
    }
    for (int slot = 0; slot < ISR_MAIN_SLOTS; ++slot) {
        if (!use[slot]) continue;
        (void)isr_decr_stack_size(&next, slot, use[slot]);
    }
    for (int i = 0; i < remainder_count; ++i)
        (void)isr_add_item_stack_to_inventory(&next, &remainders[i]);
    ICStack output = special_match
        ? special.output : ic_mk(result.item, result.count, result.meta);
    (void)isr_add_item_stack_to_inventory(&next, &output);
    if (!isr_is_empty(&output)) return 0;
    r->player.inv = next;
    for (int i = 0; i < remainder_count; ++i)
        if (!isr_is_empty(&remainders[i]))
            (void)gm_runtime_drop_player_stack(r, remainders[i]);
    return 1;
}

static int runtime_chest_adjacent_index(
        const GmRuntime *r, int chest_index) {
    static const int dx[4] = {0, 1, 0, -1};
    static const int dz[4] = {-1, 0, 1, 0};
    const GmRuntimeChest *chest;
    int block_id;
    if (!r || !r->chests || chest_index < 0
            || chest_index >= r->chests_cap)
        return -1;
    chest = &r->chests[chest_index];
    if (!chest->active)
        return -1;
    block_id = gm_world_block(
        r->world, chest->wx, chest->wy, chest->wz);
    if (!runtime_is_chest_block(block_id))
        return -1;
    for (int face = 0; face < 4; ++face) {
        int x = chest->wx + dx[face];
        int z = chest->wz + dz[face];
        if (gm_world_block(r->world, x, chest->wy, z) != block_id)
            continue;
        for (int i = 0; i < r->chests_cap; ++i)
            if (i != chest_index && r->chests[i].active
                    && r->chests[i].wx == x
                    && r->chests[i].wy == chest->wy
                    && r->chests[i].wz == z)
                return i;
    }
    return -1;
}

static void runtime_chest_notify_viewer_change(
        GmRuntime *r, int chest_index) {
    const GmRuntimeChest *chest;
    if (!r || !r->chests || chest_index < 0
            || chest_index >= r->chests_cap)
        return;
    chest = &r->chests[chest_index];
    if (!chest->active
            || gm_world_block(
                r->world, chest->wx, chest->wy, chest->wz) != 146)
        return;
    /* TileEntityChest.open/closeInventory notifies at the chest and, only
     * for Type.TRAP, at pos.down() so upward strong power propagates. */
    runtime_redstone_notify_neighbors(
        r, chest->wx, chest->wy, chest->wz);
    runtime_redstone_notify_neighbors(
        r, chest->wx, chest->wy - 1, chest->wz);
}

static void runtime_chest_open_container(
        GmRuntime *r, int chest_index) {
    int pair_index = runtime_chest_adjacent_index(r, chest_index);
    /* TileEntityChest.createContainer passes the player to fillWithLoot for a
     * single chest. InventoryLargeChest does not: its first slot access fills
     * each half with a null player, an observable vanilla 1.11.2 edge. */
    if (pair_index < 0)
        chest_live_open_luck(
            &r->chests[chest_index].state, r->player_luck);
    else
        chest_live_open(&r->chests[chest_index].state);
    runtime_chest_notify_viewer_change(r, chest_index);
    /* InventoryLargeChest.openInventory forwards to both 27-slot halves. */
    if (pair_index >= 0) {
        chest_live_open(&r->chests[pair_index].state);
        runtime_chest_notify_viewer_change(r, pair_index);
    }
    /* BlockChest.getLockableContainer always exposes the north/west half
     * first, independent of which half the player clicked. Preserve that
     * InventoryLargeChest order in the 54-slot screen. */
    if (pair_index >= 0
            && (r->chests[pair_index].wx < r->chests[chest_index].wx
                || (r->chests[pair_index].wx
                        == r->chests[chest_index].wx
                    && r->chests[pair_index].wz
                        < r->chests[chest_index].wz))) {
        r->active_chest = pair_index;
        r->active_chest_pair = chest_index;
    } else {
        r->active_chest = chest_index;
        r->active_chest_pair = pair_index;
    }
    r->container = pair_index >= 0 ? 10 : 3;
}

static void runtime_chest_close_container(
        GmRuntime *r, int chest_index) {
    int pair_index = r->active_chest == chest_index
        ? r->active_chest_pair
        : runtime_chest_adjacent_index(r, chest_index);
    chest_live_close(&r->chests[chest_index].state);
    runtime_chest_notify_viewer_change(r, chest_index);
    /* InventoryLargeChest.closeInventory mirrors the two-half open. */
    if (pair_index >= 0) {
        chest_live_close(&r->chests[pair_index].state);
        runtime_chest_notify_viewer_change(r, pair_index);
    }
}

static int runtime_chest_player_blocked(
        const GmRuntime *r, int x, int y, int z) {
    static const int dx[4] = {0, 1, 0, -1};
    static const int dz[4] = {-1, 0, 1, 0};
    int block_id = gm_world_block(r->world, x, y, z);
    if (runtime_redstone_side_solid_1_11_2(r, x, y + 1, z, 0))
        return 1;
    if (gm_mobs_sitting_ocelot_over(
            &r->mobs, r->dimension, x, y, z))
        return 1;
    for (int face = 0; face < 4; ++face) {
        int nx = x + dx[face], nz = z + dz[face];
        if (gm_world_block(r->world, nx, y, nz) == block_id
                && (runtime_redstone_side_solid_1_11_2(
                        r, nx, y + 1, nz, 0)
                    || gm_mobs_sitting_ocelot_over(
                        &r->mobs, r->dimension, nx, y, nz)))
                return 1;
    }
    return 0;
}

/* Close any open container TE bookkeeping before switching screens. */
static void runtime_close_container(GmRuntime *r)
{
    if (!r) return;
    if ((r->container == 3 || r->container == 10)
            && r->active_chest >= 0)
        runtime_chest_close_container(r, r->active_chest);
    else if (r->container == 3
            && r->active_chest == GM_ACTIVE_ENDER_CHEST
            && r->active_ender_chest >= 0
            && r->active_ender_chest < r->ender_chests_cap) {
        GmRuntimeEnderChest *tile =
            &r->ender_chests[r->active_ender_chest];
        if (tile->active && tile->num_players_using > 0)
            --tile->num_players_using;
    } else if (r->container == 9
            && r->active_chest == GM_ACTIVE_SHULKER_BOX
            && r->active_static_container >= 0
            && r->active_static_container < r->static_containers_cap) {
        GmRuntimeStaticContainer *tile =
            &r->static_containers[r->active_static_container];
        if (tile->active && runtime_is_shulker_box(tile->block)) {
            --tile->shulker_open_count;
            if (tile->shulker_open_count <= 0) {
                float pitch =
                    runtime_java_random_next_float(r) * 0.1f + 0.9f;
                tile->shulker_animation_status = GM_SHULKER_BOX_CLOSING;
                runtime_sound_event_append(
                    r, GM_SOUND_SHULKER_BOX_CLOSE,
                    GM_SOUND_CATEGORY_BLOCKS, 0, 0,
                    (double)tile->wx + 0.5,
                    (double)tile->wy + 0.5,
                    (double)tile->wz + 0.5, 0.5f, pitch);
            }
        }
    }
    gm_container_close(r);
    r->enchanting.open = 0;
    r->anvil.open = 0;
    r->container = 0;
    r->container_drag_event = 0;
    r->container_drag_mode = 0;
    memset(r->container_drag_slots, 0, sizeof r->container_drag_slots);
    r->container_cursor = ic_empty();
    r->active_furnace = -1;
    r->active_chest = -1;
    r->active_chest_pair = -1;
    r->active_ender_chest = -1;
    r->active_static_container = -1;
    r->active_villager_eid = -1;
    r->active_horse_eid = -1;
    r->merchant_selected = 0;
    r->merchant_offer_index = -1;
    memset(&r->structure_gui, 0, sizeof r->structure_gui);
}

void gm_runtime_close_open_container(GmRuntime *r)
{
    runtime_close_container(r);
}

/* InventoryHelper.spawnItemStack. The three float offsets are shared by every
 * split from one slot, while each EntityItem consumes its constructor entropy
 * before InventoryHelper overwrites motion with three Gaussian samples. */
static int runtime_drop_stack(
        GmRuntime *r, double x, double y, double z, ICStack st)
{
    JavaGaussianRandom random;
    float offset_x, offset_y, offset_z;
    int spawned = 0;
    if (!r || st.item <= 0 || st.count <= 0) return 1;
    jrand_gaussian_set_state(
        &random, r->inventory_helper_random_seed48,
        r->inventory_helper_random_have_gaussian,
        r->inventory_helper_random_gaussian);
    offset_x = jrand_float(&random.random) * 0.8F + 0.1F;
    offset_y = jrand_float(&random.random) * 0.8F + 0.1F;
    offset_z = jrand_float(&random.random) * 0.8F + 0.1F;
    while (st.count > 0) {
        ICStack split = st;
        int requested = jrand_int_bound(&random.random, 21) + 10;
        int amount = requested < st.count ? requested : st.count;
        double motion_x, motion_y, motion_z;
        float hover, yaw;
        JavaRandom entity_random;
        int64_t uuid_most, uuid_least;
        int eid;
        split.count = amount;
        st.count -= amount;

        /* EntityItem's constructor consumes four Math.random doubles. Its X/Z
         * constructor velocities are immediately overwritten below. */
        hover = (float)(runtime_math_random_next_double(r)
            * (MC_PI * 2.0));
        yaw = (float)(runtime_math_random_next_double(r) * 360.0);
        (void)runtime_math_random_next_double(r);
        (void)runtime_math_random_next_double(r);
        motion_x = jrand_gaussian_next(&random)
            * 0.05000000074505806;
        motion_y = jrand_gaussian_next(&random)
            * 0.05000000074505806 + 0.20000000298023224;
        motion_z = jrand_gaussian_next(&random)
            * 0.05000000074505806;
        eid = r->next_entity_id++;
        jrand_set(&entity_random, runtime_java_random_seed_next_long(
            &r->entity_seed_generator_seed48));
        runtime_next_server_uuid(r, &uuid_most, &uuid_least);
        if (!gm_live_spawn_stack_exact_hover(
                &r->entities, eid,
                x + (double)offset_x,
                y + (double)offset_y,
                z + (double)offset_z,
                motion_x, motion_y, motion_z, yaw, hover,
                split, 0, 0, 0)
                || !gm_live_set_item_environment_state(
                    &r->entities, eid, entity_random.seed, -1, 0, 1)
                || !gm_runtime_set_item_entity_uuid(
                    r, eid, uuid_most, uuid_least)
                || !runtime_loaded_entity_order_append(r, eid)) {
            r->inventory_helper_random_seed48 = random.random.seed;
            r->inventory_helper_random_have_gaussian =
                random.have_next_next_gaussian;
            r->inventory_helper_random_gaussian =
                random.next_next_gaussian;
            return 0;
        }
        ++spawned;
    }
    r->inventory_helper_random_seed48 = random.random.seed;
    r->inventory_helper_random_have_gaussian =
        random.have_next_next_gaussian;
    r->inventory_helper_random_gaussian = random.next_next_gaussian;
    return spawned > 0;
}

int gm_runtime_inventory_helper_drop_fixture(
        GmRuntime *r, int x, int y, int z, ICStack stack) {
    return runtime_drop_stack(r, x, y, z, stack);
}

/* Materialize deferred structure loot (or live TE slots) and drop all stacks.
 * Vanilla: breakBlock -> InventoryHelper after fillWithLoot on first access. */
static void runtime_drop_chest_contents(GmRuntime *r, ChestLive *ch, int wx, int wy, int wz)
{
    int s;
    if (!r || !ch) return;
    chest_live_ensure_loot(ch);
    for (s = 0; s < CHEST_LIVE_SLOTS; ++s) {
        ICStack st = chest_live_get(ch, s);
        runtime_drop_stack(r, wx, wy, wz, st);
    }
}

/* TileEntityChest break: drop every slot (after deferred loot fill) and free
 * the TE so a replacement chest at the same block starts empty. Unopened
 * structure chests with no TE still materialize deferred loot on break. */
static void runtime_break_chest_te(GmRuntime *r, int wx, int wy, int wz)
{
    if (!r || !r->chests) return;
    for (int i = 0; i < r->chests_cap; ++i) {
        GmRuntimeChest *c = &r->chests[i];
        if (!c->active || c->wx != wx || c->wy != wy || c->wz != wz) continue;
        runtime_drop_chest_contents(r, &c->state, wx, wy, wz);
        if ((r->container == 3 || r->container == 10)
                && (r->active_chest == i || r->active_chest_pair == i))
            runtime_close_container(r);
        c->active = 0;
        chest_live_init(&c->state);
        return;
    }
    /* No TE yet: unopened structure chest still drops deferred loot. */
    {
        int tid = -1;
        long long lseed = 0;
        if (gm_world_block(r->world, wx, wy, wz) == 54
                && runtime_generated_chest_info(
                    r, wx, wy, wz, &tid, &lseed)) {
            ChestLive tmp;
            chest_live_init(&tmp);
            chest_live_set_loot(&tmp, tid, lseed);
            runtime_drop_chest_contents(r, &tmp, wx, wy, wz);
        }
    }
}

/* TileEntityFurnace break: drop all three inventory slots and retire the
 * fixed-pool entry. A 61<->62 lit-state transition keeps the same tile. */
static void runtime_break_furnace_te(GmRuntime *r, int wx, int wy, int wz)
{
    if (!r) return;
    for (int i = 0; i < r->furnaces_cap; ++i) {
        GmRuntimeFurnace *f = &r->furnaces[i];
        if (!f->active || f->wx != wx || f->wy != wy || f->wz != wz)
            continue;
        for (int slot = 0; slot < FURNACE_LIVE_SLOT_COUNT; ++slot) {
            ICStack stack = furnace_live_get_ic(&f->state, slot);
            if (!isr_is_empty(&stack))
                (void)runtime_drop_stack(r, wx, wy, wz, stack);
        }
        if (r->container == 2 && r->active_furnace == i)
            runtime_close_container(r);
        f->active = 0;
        f->custom_name = 0;
        furnace_live_init(&f->state);
        return;
    }
}

/* Static inventory break mirrors InventoryHelper.dropInventoryItems. The
 * active comparator-only slice has no GUI/tick path, but replacement must
 * still retire and preserve every represented stack. */
static void runtime_break_static_container_te(
        GmRuntime *r, int wx, int wy, int wz) {
    if (!r || !r->static_containers) return;
    for (int i = 0; i < r->static_containers_cap; ++i) {
        GmRuntimeStaticContainer *container =
            &r->static_containers[i];
        if (!container->active
                || container->dimension != r->dimension
                || container->wx != wx || container->wy != wy
                || container->wz != wz)
            continue;
        if (runtime_is_shulker_box(container->block)) {
            if (r->container == 9
                    && r->active_static_container == i)
                runtime_close_container(r);
            (void)runtime_spawn_shulker_box_item(
                r, wx, wy, wz, container->block, container);
            gm_nbt_blob_clear(&container->item_tag);
            memset(container, 0, sizeof *container);
            return;
        }
        if (r->active_static_container == i)
            runtime_close_container(r);
        for (int slot = 0; slot < container->size; ++slot)
            (void)runtime_drop_stack(
                r, wx, wy, wz, container->slots[slot]);
        memset(container, 0, sizeof *container);
        return;
    }
}

/* Command blocks in the bounded comparator slice carry only the inert saved
 * success count. Replacing the block retires that represented tile. */
static void runtime_break_command_block_te(
        GmRuntime *r, int wx, int wy, int wz) {
    if (!r || !r->command_blocks) return;
    for (int i = 0; i < r->command_blocks_cap; ++i) {
        GmRuntimeCommandBlock *command = &r->command_blocks[i];
        if (!command->active
                || command->dimension != r->dimension
                || command->wx != wx || command->wy != wy
                || command->wz != wz)
            continue;
        memset(command, 0, sizeof *command);
        return;
    }
}

/* Free slot for a new TE. Never evicts a live chest while its block exists.
 * Reclaims slots whose block is gone; grows the table when full. */
static int runtime_chest_free_slot(GmRuntime *r, int wx, int wy, int wz)
{
    int free_slot = -1;
    if (!r || !r->chests) return -1;
    for (int i = 0; i < r->chests_cap; ++i) {
        GmRuntimeChest *c = &r->chests[i];
        if (!c->active) {
            if (free_slot < 0) free_slot = i;
            continue;
        }
        if (c->wx == wx && c->wy == wy && c->wz == wz) return i;
        /* Reclaim only when the world no longer has a chest block here. */
        if (!runtime_is_chest_block(
                gm_world_block(r->world, c->wx, c->wy, c->wz))) {
            if ((r->container == 3 || r->container == 10)
                    && (r->active_chest == i || r->active_chest_pair == i))
                runtime_close_container(r);
            c->active = 0;
            chest_live_init(&c->state);
            if (free_slot < 0) free_slot = i;
        }
    }
    if (free_slot >= 0) return free_slot;
    /* Grow: never drop inventory of a live block-backed TE. */
    {
        int new_cap = r->chests_cap > 0 ? r->chests_cap * 2 : GM_RUNTIME_CHESTS_INITIAL;
        GmRuntimeChest *grown = (GmRuntimeChest *)realloc(
            r->chests, (size_t)new_cap * sizeof(GmRuntimeChest));
        if (!grown) return -1; /* fail safely: no open, no loss */
        memset(grown + r->chests_cap, 0,
               (size_t)(new_cap - r->chests_cap) * sizeof(GmRuntimeChest));
        free_slot = r->chests_cap;
        r->chests = grown;
        r->chests_cap = new_cap;
        return free_slot;
    }
}

static int runtime_chest_ensure_tile(
        GmRuntime *r, int x, int y, int z) {
    int index = runtime_chest_free_slot(r, x, y, z);
    if (index < 0) return -1;
    GmRuntimeChest *chest = &r->chests[index];
    if (!chest->active) {
        chest->active = 1;
        chest->wx = x;
        chest->wy = y;
        chest->wz = z;
        chest_live_init(&chest->state);
    }
    return index;
}

static int runtime_ender_chest_ensure_tile(
        GmRuntime *r, int dimension, int x, int y, int z) {
    int free_index = -1;
    if (!r || dimension < -1 || dimension > 1) return -1;
    for (int index = 0; index < r->ender_chests_cap; ++index) {
        GmRuntimeEnderChest *tile = &r->ender_chests[index];
        if (tile->active && tile->dimension == dimension
                && tile->wx == x && tile->wy == y && tile->wz == z)
            return index;
        if (!tile->active && free_index < 0) free_index = index;
    }
    if (free_index < 0) {
        int old_cap = r->ender_chests_cap;
        int new_cap = old_cap > 0
            ? old_cap * 2 : GM_RUNTIME_ENDER_CHESTS_INITIAL;
        GmRuntimeEnderChest *grown =
            (GmRuntimeEnderChest *)realloc(
                r->ender_chests,
                (size_t)new_cap * sizeof *r->ender_chests);
        if (!grown) return -1;
        memset(grown + old_cap, 0,
               (size_t)(new_cap - old_cap) * sizeof *grown);
        r->ender_chests = grown;
        r->ender_chests_cap = new_cap;
        free_index = old_cap;
    }
    GmRuntimeEnderChest *tile = &r->ender_chests[free_index];
    memset(tile, 0, sizeof *tile);
    tile->active = 1;
    tile->dimension = dimension;
    tile->wx = x;
    tile->wy = y;
    tile->wz = z;
    return free_index;
}

static void runtime_ender_chest_remove(
        GmRuntime *r, int dimension, int x, int y, int z) {
    if (!r) return;
    for (int index = 0; index < r->ender_chests_cap; ++index) {
        GmRuntimeEnderChest *tile = &r->ender_chests[index];
        if (!tile->active || tile->dimension != dimension
                || tile->wx != x || tile->wy != y || tile->wz != z)
            continue;
        if (r->container == 3
                && r->active_chest == GM_ACTIVE_ENDER_CHEST
                && r->active_ender_chest == index)
            runtime_close_container(r);
        memset(tile, 0, sizeof *tile);
        return;
    }
}

int gm_runtime_chest_set_slot(
        GmRuntime *r, int dimension, int x, int y, int z,
        int slot, int item, int count, int meta) {
    static const int dx[4] = {0, 1, 0, -1};
    static const int dz[4] = {-1, 0, 1, 0};
    int adjacent_count = 0;
    int block_id;
    if (!r || !r->world || dimension != r->dimension
            || y < 0 || y > 255 || slot < 0
            || slot >= CHEST_LIVE_SLOTS
            || item < 0 || item > 4095
            || count < 0 || count > TEC_STACK_LIMIT
            || meta < 0 || meta > 32767
            || (item == 0) != (count == 0))
        return 0;
    block_id = gm_world_block(r->world, x, y, z);
    if (!runtime_is_chest_block(block_id))
        return 0;
    for (int face = 0; face < 4; ++face) {
        if (gm_world_block(
                r->world, x + dx[face], y, z + dz[face]) == block_id)
            adjacent_count++;
    }
    if (adjacent_count > 1)
        return 0;
    if (item != 0 && count > tec_max_stack_size(item))
        return 0;
    int index = runtime_chest_ensure_tile(r, x, y, z);
    if (index < 0) return 0;
    GmRuntimeChest *chest = &r->chests[index];
    chest_live_set(
        &chest->state, slot,
        item == 0 ? ic_empty() : ic_mk(item, count, meta));
    return 1;
}

int gm_runtime_chest_set_transient(
        GmRuntime *r, int dimension, int x, int y, int z,
        int num_players_using, uint32_t lid_angle_bits,
        uint32_t prev_lid_angle_bits, int ticks_since_sync) {
    union { uint32_t u; float f; } lid, prev;
    GmRuntimeChest *chest;
    if (!r || !r->world || dimension != r->dimension
            || y < 0 || y > 255 || num_players_using < 0)
        return 0;
    lid.u = lid_angle_bits;
    prev.u = prev_lid_angle_bits;
    if (!isfinite(lid.f) || !isfinite(prev.f)
            || lid.f < 0.0F || lid.f > 1.0F
            || prev.f < 0.0F || prev.f > 1.0F
            || (num_players_using > 0
                && (lid.f < prev.f || lid.f - prev.f > 0.100001F))
            || (num_players_using == 0
                && (lid.f > prev.f || prev.f - lid.f > 0.100001F)))
        return 0;
    chest = (GmRuntimeChest *)runtime_chest_tile_raw_at(r, x, y, z);
    if (!chest || !runtime_is_chest_block(
            gm_world_block(r->world, x, y, z)))
        return 0;
    chest->state.te.num_players_using = num_players_using;
    chest->state.te.lid_angle = lid.f;
    chest->state.te.prev_lid_angle = prev.f;
    chest->state.te.ticks_since_sync = ticks_since_sync;
    return 1;
}

int gm_runtime_container_set_stack_tag(
        GmRuntime *r, int dimension, int x, int y, int z, int slot,
        const void *tag_nbt, size_t tag_nbt_len) {
    ICStack *stack = NULL;
    int tag_id;
    int block;
    if (!r || !tag_nbt || tag_nbt_len == 0
            || dimension != r->dimension || y < 0 || y > 255
            || slot < 0)
        return 0;
    block = gm_world_block(r->world, x, y, z);
    if (runtime_is_chest_block(block)) {
        GmRuntimeChest *chest = (GmRuntimeChest *)
            runtime_chest_tile_raw_at(r, x, y, z);
        if (!chest || slot >= CHEST_LIVE_SLOTS) return 0;
        {
            TecStack *compact = &chest->state.te.slots[slot];
            if (tec_is_empty(compact)) return 0;
            tag_id = gm_runtime_stack_tag_intern(r, tag_nbt, tag_nbt_len);
            if (tag_id == 0) return 0;
            compact->tag_id = tag_id;
            return 1;
        }
    }
    if (block == 61 || block == 62) {
        GmRuntimeFurnace *furnace = (GmRuntimeFurnace *)
            runtime_furnace_at(r, x, y, z);
        ICStack exact;
        if (!furnace || slot >= FURNACE_LIVE_SLOT_COUNT) return 0;
        exact = furnace_live_get_ic(&furnace->state, slot);
        if (isr_is_empty(&exact)) return 0;
        tag_id = gm_runtime_stack_tag_intern(r, tag_nbt, tag_nbt_len);
        if (tag_id == 0) return 0;
        exact.tag_id = tag_id;
        furnace_live_set_ic(&furnace->state, slot, exact);
        return 1;
    }
    for (int index = 0; index < r->static_containers_cap; ++index) {
        GmRuntimeStaticContainer *container = &r->static_containers[index];
        if (!container->active || container->dimension != dimension
                || container->wx != x || container->wy != y
                || container->wz != z)
            continue;
        if (slot >= container->size) return 0;
        stack = &container->slots[slot];
        break;
    }
    if (!stack) return 0;
    if (isr_is_empty(stack)) return 0;
    tag_id = gm_runtime_stack_tag_intern(r, tag_nbt, tag_nbt_len);
    if (tag_id == 0) return 0;
    stack->tag_id = tag_id;
    return 1;
}

int gm_runtime_use_block(GmRuntime *r, int wx, int wy, int wz) {
    if (!r || !r->world) return 0;
    GmPlayerView v; gm_runtime_view(r, &v);
    double dx = (wx + 0.5) - v.x;
    double dy = (wy + 0.5) - (v.y + v.eye_height);
    double dz = (wz + 0.5) - v.z;
    if (dx*dx + dy*dy + dz*dz > 36.0) return 0;
    int id = gm_world_block(r->world, wx, wy, wz);
    if (id == 122) {
        for (int attempt = 0; attempt < 1000; ++attempt) {
            int x = wx + runtime_java_random_next_int(r, 16)
                - runtime_java_random_next_int(r, 16);
            int y = wy + runtime_java_random_next_int(r, 8)
                - runtime_java_random_next_int(r, 8);
            int z = wz + runtime_java_random_next_int(r, 16)
                - runtime_java_random_next_int(r, 16);
            if (y < 0 || y > 255
                    || gm_world_block(r->world, x, y, z) != 0)
                continue;
            if (!gm_runtime_set_block(r, x, y, z, 122, 0))
                return 0;
            return gm_runtime_set_block(r, wx, wy, wz, 0, 0);
        }
        return 1;
    }
    if (id == 73 || id == 74) {
        /* BlockRedstoneOre.spawnParticles takes three World.rand floats for
         * each face even on the integrated server; particle transport itself
         * is client-only state and does not alter the callback result. */
        for (int draw = 0; draw < 18; ++draw)
            (void)runtime_java_random_next_float(r);
        if (id == 73)
            gm_world_set_block_meta(r->world, wx, wy, wz, 74, 0);
        return 0;
    }
    if (id == 118) {
        ICStack held = isr_get_stack(
            &r->player.inv, r->player.inv.current_item);
        int level = gm_world_meta(r->world, wx, wy, wz);
        if (held.count <= 0)
            return 1;
        if (held.item == 326) {
            if (level < 3) {
                if (!r->tape_creative)
                    isr_set_stack(
                        &r->player.inv, r->player.inv.current_item,
                        ic_mk(325, 1, 0));
                gm_world_set_block_meta(r->world, wx, wy, wz, 118, 3);
                runtime_redstone_update_comparator_output_level(
                    r, wx, wy, wz);
            }
            return 1;
        }
        return 0;
    }
    if (id == 36) {
        for (int index = 0; index < r->piston_count; ++index) {
            const GmRuntimePiston *piston = &r->pistons[index];
            if (piston->active && piston->dimension == r->dimension
                    && piston->x == wx && piston->y == wy
                    && piston->z == wz)
                return 0;
        }
        return gm_runtime_set_block(r, wx, wy, wz, 0, 0);
    }
    if (runtime_is_fence_id(id)) {
        /* On the client an empty hand is accepted before the authoritative
         * ItemLead attachment attempt. This preserves the physical swing;
         * lead-bearing interactions are handled by the entity/leash path. */
        ICStack held = isr_get_stack(
            &r->player.inv, r->player.inv.current_item);
        return held.count <= 0;
    }
    if (id == 63 || id == 68)
        return 1;
    if (id == 137 || id == 210 || id == 211)
        return r->tape_creative != 0;
    if (id == 25) {
        GmRuntimeNoteBlock *note = runtime_note_block_at(
            r, r->dimension, wx, wy, wz);
        if (!note && gm_runtime_note_block_set(
                r, r->dimension, wx, wy, wz, 0, 0))
            note = runtime_note_block_at(r, r->dimension, wx, wy, wz);
        if (!note) return 0;
        note->note = (note->note + 1) % 25;
        runtime_note_block_trigger(r, wx, wy, wz, note->note);
        return 1;
    }
    if (id == 46) {
        ICStack held = isr_get_stack(
            &r->player.inv, r->player.inv.current_item);
        if (held.count <= 0 || (held.item != 259 && held.item != 385)
                || !runtime_tnt_prime(r, wx, wy, wz))
            return 0;
        gm_world_set_block_meta(r->world, wx, wy, wz, 0, 0);
        runtime_redstone_notify_neighbors(r, wx, wy, wz);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        if (held.item == 259) {
            ++held.meta;
            if (held.meta > 64)
                (void)isr_decr_stack_size(
                    &r->player.inv, r->player.inv.current_item, 1);
            else
                isr_set_stack(
                    &r->player.inv, r->player.inv.current_item, held);
        } else {
            (void)isr_decr_stack_size(
                &r->player.inv, r->player.inv.current_item, 1);
        }
        return 1;
    }
    if (id == 69) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        gm_world_set_block_meta(
            r->world, wx, wy, wz, id, meta ^ 8);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        runtime_redstone_button_notify(r, wx, wy, wz, id, meta);
        return 1;
    }
    if (id == 77 || id == 143) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        if ((meta & 8) != 0)
            return 1;
        if (!runtime_schedule_tick_insert(
                r, wx, wy, wz, id,
                r->clock.total_time + (id == 143 ? 30 : 20),
                0, r->scheduled_tick_next_order))
            return 0;
        gm_world_set_block_meta(
            r->world, wx, wy, wz, id, meta | 8);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        runtime_redstone_button_notify(r, wx, wy, wz, id, meta);
        return 1;
    }
    if (id == 93 || id == 94) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        int next_delay = ((meta >> 2) + 1) & 3;
        gm_world_set_block_meta(
            r->world, wx, wy, wz, id, (meta & 3) | (next_delay << 2));
        runtime_redstone_notify_neighbors(r, wx, wy, wz);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        return 1;
    }
    if (id == 149 || id == 150) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        if (!runtime_comparator_find_mut(
                r, r->dimension, wx, wy, wz))
            return 0;
        gm_world_set_block_meta(r->world, wx, wy, wz, id, meta ^ 4);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        runtime_redstone_comparator_dispatch(r, wx, wy, wz, id);
        return 1;
    }
    if (id == 151 || id == 178) {
        int next_id = id == 151 ? 178 : 151;
        int next_meta = runtime_redstone_daylight_power(
            r, wx, wy, wz, next_id == 178);
        if (!runtime_daylight_detector_ensure(
                r, r->dimension, wx, wy, wz))
            return 0;
        gm_world_set_block_meta(
            r->world, wx, wy, wz, next_id, next_meta);
        runtime_redstone_notify_neighbors(r, wx, wy, wz);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        return 1;
    }
    if (id == 64 || (id >= 193 && id <= 197)) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        int lower_y = (meta & 8) != 0 ? wy - 1 : wy;
        if (lower_y < 0
                || gm_world_block(r->world, wx, lower_y, wz) != id)
            return 0;
        int lower_meta = gm_world_meta(r->world, wx, lower_y, wz);
        if ((lower_meta & 8) != 0)
            return 0;
        gm_world_set_block_meta(
            r->world, wx, lower_y, wz, id, lower_meta ^ 4);
        runtime_redstone_update_observers_at(r, wx, lower_y, wz);
        return 1;
    }
    if (id == 96) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        gm_world_set_block_meta(r->world, wx, wy, wz, id, meta ^ 4);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        return 1;
    }
    if (runtime_is_fence_gate_id(id)) {
        int meta = gm_world_meta(r->world, wx, wy, wz);
        if ((meta & 4) != 0) {
            meta &= ~4;
        } else {
            int facing = (int)floor(
                (double)r->server_player.yaw / 90.0 + 0.5) & 3;
            if ((meta & 3) == (facing ^ 2))
                meta = (meta & ~3) | facing;
            meta |= 4;
        }
        gm_world_set_block_meta(r->world, wx, wy, wz, id, meta);
        runtime_redstone_update_observers_at(r, wx, wy, wz);
        return 1;
    }
    if (id == 92) {
        int bites = gm_world_meta(r->world, wx, wy, wz);
        if (r->vitals.foodLevel >= 20)
            return 1;
        if (bites < 0 || bites > 6)
            return 0;
        if (!gm_runtime_set_block(
                r, wx, wy, wz, bites < 6 ? 92 : 0,
                bites < 6 ? bites + 1 : 0))
            return 0;
        {
            int food = r->vitals.foodLevel + 2;
            float saturation;
            if (food > 20) food = 20;
            r->vitals.foodLevel = food;
            saturation = r->vitals.saturation
                + (float)2 * 0.1f * 2.0f;
            r->vitals.saturation = saturation < (float)food
                ? saturation : (float)food;
            r->player.food = (float)food;
            r->server_player.food = (float)food;
        }
        return 1;
    }
    if (id == 140) {
        ICStack held = isr_get_stack(
            &r->player.inv, r->player.inv.current_item);
        return held.count > 0 && runtime_flower_pot_insert(
            r, wx, wy, wz, held.item, held.meta, 1);
    }
    if (id == 84) {
        if (gm_world_meta(r->world, wx, wy, wz) != 0)
            return runtime_jukebox_eject_record(r, wx, wy, wz);
        ICStack held = isr_get_stack(
            &r->player.inv, r->player.inv.current_item);
        return held.count > 0 && runtime_jukebox_insert_record(
            r, wx, wy, wz, held.item, held.meta, 1);
    }
    if (id == 255) {
        if (!runtime_structure_block_ensure_default(
                r, r->dimension, wx, wy, wz))
            return 0;
        /* EntityPlayer.canUseCommandBlock requires creative capability in
         * 1.11.2. The GUI owns no inventory, so its open state is just the
         * block coordinate and a distinct screen id. */
        if (!r->tape_creative)
            return 0;
        if (!gm_runtime_structure_gui_open(
                r, r->dimension, wx, wy, wz)) {
            runtime_close_container(r);
            return 0;
        }
        return 1;
    }
    if (id == 58) {
        runtime_close_container(r); /* return any live grid/cursor before switching */
        r->container=1; r->container_wx=wx; r->container_wy=wy; r->container_wz=wz;
        return 1;
    }
    if (id == 23 || id == 158 || id == 154) {
        int index = -1;
        runtime_close_container(r);
        if (id == 23 && !runtime_static_container_at(r, wx, wy, wz))
            (void)runtime_generated_dispenser_ensure(
                r, wx, wy, wz, r->player_luck);
        if (!runtime_static_container_at(r, wx, wy, wz)
                && !gm_runtime_static_container_set_slot(
                    r, r->dimension, wx, wy, wz, 0, 0, 0, 0))
            return 0;
        for (int i = 0; i < r->static_containers_cap; ++i) {
            GmRuntimeStaticContainer *inventory = &r->static_containers[i];
            if (inventory->active
                    && inventory->dimension == r->dimension
                    && inventory->wx == wx && inventory->wy == wy
                    && inventory->wz == wz && inventory->block == id) {
                index = i;
                break;
            }
        }
        if (index < 0) return 0;
        r->container = id == 154 ? 14 : 13;
        r->active_static_container = index;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (id == 61 || id == 62) {
        runtime_close_container(r);
        int free_slot = -1;
        for (int i = 0; i < r->furnaces_cap; ++i) {
            GmRuntimeFurnace *f = &r->furnaces[i];
            if (f->active && f->wx==wx && f->wy==wy && f->wz==wz) {
                r->container=2; r->active_furnace=i;
                r->container_wx=wx; r->container_wy=wy; r->container_wz=wz;
                return 1;
            }
            if (!f->active && free_slot < 0) free_slot=i;
        }
        if (free_slot < 0) return 0;
        GmRuntimeFurnace *f=&r->furnaces[free_slot];
        f->active=1; f->wx=wx; f->wy=wy; f->wz=wz; f->custom_name=0;
        furnace_live_init(&f->state);
        r->container=2; r->active_furnace=free_slot;
        r->container_wx=wx; r->container_wy=wy; r->container_wz=wz;
        return 1;
    }
    if (id == 116) {
        GmPlayerView view;
        if (!r->enchanting_enabled) return 1;
        runtime_close_container(r);
        gm_runtime_view(r, &view);
        if (r->player_xp_level < 0)
            r->player_xp_level = view.xp_level;
        enchanting_live_open(
            &r->enchanting, r->world, wx, wy, wz,
            r->player_xp_seed);
        r->container = 5;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (id == 145) {
        if (!r->enchanting_enabled) return 1;
        runtime_close_container(r);
        gm_anvil_live_open(&r->anvil, wx, wy, wz);
        r->container = 6;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (id == 117) {
        int index = -1;
        if (!r->brewing_enabled) return 1;
        runtime_close_container(r);
        for (int i = 0; i < r->static_containers_cap; ++i) {
            GmRuntimeStaticContainer *stand = &r->static_containers[i];
            if (stand->active && stand->dimension == r->dimension
                    && stand->wx == wx && stand->wy == wy
                    && stand->wz == wz && stand->block == 117) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            if (!gm_runtime_static_container_set_slot(
                    r, r->dimension, wx, wy, wz, 0, 0, 0, 0))
                return 0;
            for (int i = 0; i < r->static_containers_cap; ++i) {
                GmRuntimeStaticContainer *stand = &r->static_containers[i];
                if (stand->active && stand->dimension == r->dimension
                        && stand->wx == wx && stand->wy == wy
                        && stand->wz == wz && stand->block == 117) {
                    index = i;
                    break;
                }
            }
        }
        if (index < 0) return 0;
        r->container = 4;
        r->active_static_container = index;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (id == 138) {
        int index = -1;
        runtime_close_container(r);
        for (int i = 0; i < r->static_containers_cap; ++i) {
            GmRuntimeStaticContainer *beacon = &r->static_containers[i];
            if (beacon->active && beacon->dimension == r->dimension
                    && beacon->wx == wx && beacon->wy == wy
                    && beacon->wz == wz && beacon->block == 138) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            if (!gm_runtime_static_container_set_slot(
                    r, r->dimension, wx, wy, wz, 0, 0, 0, 0))
                return 1;
            for (int i = 0; i < r->static_containers_cap; ++i) {
                GmRuntimeStaticContainer *beacon = &r->static_containers[i];
                if (beacon->active && beacon->dimension == r->dimension
                        && beacon->wx == wx && beacon->wy == wy
                        && beacon->wz == wz && beacon->block == 138) {
                    index = i;
                    break;
                }
            }
        }
        if (index >= 0) {
            r->container = 11;
            r->active_static_container = index;
            r->container_wx = wx;
            r->container_wy = wy;
            r->container_wz = wz;
        }
        return 1;
    }
    if (runtime_is_shulker_box(id)) {
        int index = -1;
        int facing = gm_world_meta(r->world, wx, wy, wz) % 6;
        for (int i = 0; i < r->static_containers_cap; ++i) {
            GmRuntimeStaticContainer *box = &r->static_containers[i];
            if (box->active && box->dimension == r->dimension
                    && box->wx == wx && box->wy == wy && box->wz == wz
                    && box->block == id) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            if (!gm_runtime_static_container_set_slot(
                    r, r->dimension, wx, wy, wz, 0, 0, 0, 0))
                return 0;
            for (int i = 0; i < r->static_containers_cap; ++i) {
                GmRuntimeStaticContainer *box = &r->static_containers[i];
                if (box->active && box->dimension == r->dimension
                        && box->wx == wx && box->wy == wy
                        && box->wz == wz && box->block == id) {
                    index = i;
                    break;
                }
            }
        }
        if (index < 0) return 0;
        GmRuntimeStaticContainer *box = &r->static_containers[index];
        if (box->shulker_animation_status == GM_SHULKER_BOX_CLOSED) {
            McAABB extension = runtime_shulker_box_top_aabb(
                box, facing, 1.0f);
            if (runtime_hanging_box_hits_block(r, &extension))
                return 1;
        }
        runtime_close_container(r);
        if (box->shulker_open_count < 0)
            box->shulker_open_count = 0;
        ++box->shulker_open_count;
        if (box->shulker_open_count == 1) {
            float pitch =
                runtime_java_random_next_float(r) * 0.1f + 0.9f;
            box->shulker_animation_status = GM_SHULKER_BOX_OPENING;
            runtime_sound_event_append(
                r, GM_SOUND_SHULKER_BOX_OPEN,
                GM_SOUND_CATEGORY_BLOCKS, 0, 0,
                (double)wx + 0.5, (double)wy + 0.5,
                (double)wz + 0.5, 0.5f, pitch);
        }
        r->container = 9;
        r->active_chest = GM_ACTIVE_SHULKER_BOX;
        r->active_chest_pair = -1;
        r->active_static_container = index;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (id == 130) {
        int above_id = wy < 255
            ? gm_world_block(r->world, wx, wy + 1, wz) : 0;
        int above_meta = wy < 255
            ? gm_world_meta(r->world, wx, wy + 1, wz) : 0;
        /* BlockEnderChest consumes the activation even when a normal cube
         * above it prevents the server from opening InventoryEnderChest. */
        if (gm_block_is_normal_cube_1_11_2(above_id, above_meta))
            return 1;
        runtime_close_container(r);
        int index = runtime_ender_chest_ensure_tile(
            r, r->dimension, wx, wy, wz);
        if (index < 0) return 1;
        ++r->ender_chests[index].num_players_using;
        r->container = 3;
        r->active_chest = GM_ACTIVE_ENDER_CHEST;
        r->active_chest_pair = -1;
        r->active_ender_chest = index;
        r->container_wx = wx;
        r->container_wy = wy;
        r->container_wz = wz;
        return 1;
    }
    if (runtime_is_chest_block(id)) {
        if (runtime_chest_player_blocked(r, wx, wy, wz)) return 0;
        runtime_close_container(r);
        if (!r->chests) return 0;
        for (int i = 0; i < r->chests_cap; ++i) {
            GmRuntimeChest *c = &r->chests[i];
            if (c->active && c->wx==wx && c->wy==wy && c->wz==wz) {
                runtime_chest_open_container(r, i);
                r->container_wx=wx; r->container_wy=wy; r->container_wz=wz;
                return 1;
            }
        }
        int free_slot = runtime_chest_free_slot(r, wx, wy, wz);
        if (free_slot < 0) return 0;
        GmRuntimeChest *c=&r->chests[free_slot];
        c->active=1; c->wx=wx; c->wy=wy; c->wz=wz;
        chest_live_init(&c->state);
        {
            int tid = -1; long long lseed = 0;
            if (id == 54
                    && runtime_generated_chest_info(
                        r, wx, wy, wz, &tid, &lseed))
                chest_live_set_loot(&c->state, tid, lseed);
        }
        runtime_chest_open_container(r, free_slot);
        r->container_wx=wx; r->container_wy=wy; r->container_wz=wz;
        return 1;
    }
    if(id==120){
        ICStack held=isr_get_stack(&r->player.inv,r->player.inv.current_item);
        if(held.item!=381||held.count<=0||(gm_world_meta(r->world,wx,wy,wz)&4))return 0;
        if(!gm_end_portal_insert_eye(r->world,wx,wy,wz))return 0;
        (void)isr_decr_stack_size(&r->player.inv,r->player.inv.current_item,1);
        return 1;
    }
    if(id==26){
        if(r->dimension==0){
            long long day=r->clock.world_time/24000LL;
            r->clock.world_time=(day+1)*24000LL;return 1;
        }
        for(int x=wx-1;x<=wx+1;++x)for(int z=wz-1;z<=wz+1;++z)
            if(gm_world_block(r->world,x,wy,z)==26)gm_world_set_block(r->world,x,wy,z,0);
        runtime_explode_with_flags(
            r,wx+0.5,wy+0.5,wz+0.5,5.0f,1,0,1);return 1;
    }
    return 0;
}

int gm_runtime_enchant_click(GmRuntime *r, int button)
{
    if (!r || r->container != 5 || !r->enchanting.open
            || !r->enchanting_enabled || button < 0 || button > 2)
        return 0;
    if (!enchanting_live_apply(
            &r->enchanting, r->world, button, 0,
            &r->player_xp_level, &r->mobs.player_random))
        return 0;
    r->player_xp_seed = r->enchanting.xp_seed;
    /* World.playSound pitch consumes one World.rand float after offers update. */
    (void)runtime_java_random_next_float(r);
    return 1;
}

int gm_runtime_furnace_insert(GmRuntime *r, int furnace_slot,
                              int inventory_slot, int amount) {
    if (!r || r->container!=2 || r->active_furnace<0 || amount<=0 ||
        inventory_slot<0 || inventory_slot>=ISR_MAIN_SLOTS) return 0;
    ICStack src=isr_get_stack(&r->player.inv,inventory_slot);
    if (isr_is_empty(&src)) return 0;
    if (src.count>amount) src.count=amount;
    GmRuntimeFurnace *furnace = &r->furnaces[r->active_furnace];
    int moved=furnace_live_insert_ic(
        &furnace->state,furnace_slot,src);
    if (moved>0) {
        (void)isr_decr_stack_size(&r->player.inv,inventory_slot,moved);
        runtime_redstone_update_comparator_output_level(
            r, furnace->wx, furnace->wy, furnace->wz);
    }
    return moved;
}

int gm_runtime_furnace_extract(GmRuntime *r, int furnace_slot, int amount) {
    if (!r || r->container!=2 || r->active_furnace<0 || amount<=0) return 0;
    GmRuntimeFurnace *furnace=&r->furnaces[r->active_furnace];
    FurnaceLive *f=&furnace->state;
    ICStack src = furnace_live_get_ic(f, furnace_slot);
    if (isr_is_empty(&src)) return 0;
    int n=src.count<amount?src.count:amount;
    IsrInv next=r->player.inv;
    ICStack out=src;
    out.count=n;
    (void)isr_add_item_stack_to_inventory(&next,&out);
    int moved=n-out.count;
    if (moved<=0) return 0;
    (void)furnace_live_extract_ic(f,furnace_slot,moved);
    r->player.inv=next;
    if (furnace_slot == FURNACE_LIVE_SLOT_OUTPUT) {
        src.count = moved;
        (void)gm_runtime_furnace_output_taken(r, src, moved);
    }
    runtime_redstone_update_comparator_output_level(
        r, furnace->wx, furnace->wy, furnace->wz);
    return moved;
}

void gm_runtime_brewing_changed(GmRuntime *r) {
    if (!r || r->container != 4 || r->active_static_container < 0
            || r->active_static_container >= r->static_containers_cap)
        return;
    GmRuntimeStaticContainer *stand =
        &r->static_containers[r->active_static_container];
    if (!stand->active || stand->block != 117) return;
    runtime_redstone_update_comparator_output_level(
        r, stand->wx, stand->wy, stand->wz);
}

void gm_runtime_shulker_box_changed(GmRuntime *r) {
    if (!r || r->container != 9 || r->active_static_container < 0
            || r->active_static_container >= r->static_containers_cap)
        return;
    GmRuntimeStaticContainer *box =
        &r->static_containers[r->active_static_container];
    if (!box->active || !runtime_is_shulker_box(box->block)) return;
    runtime_redstone_update_comparator_output_level(
        r, box->wx, box->wy, box->wz);
}

void gm_runtime_static_container_changed(GmRuntime *r) {
    GmRuntimeStaticContainer *inventory;
    if (!r || (r->container != 13 && r->container != 14)
            || r->active_static_container < 0
            || r->active_static_container >= r->static_containers_cap)
        return;
    inventory = &r->static_containers[r->active_static_container];
    if (!inventory->active
            || (inventory->block != 23 && inventory->block != 158
                && inventory->block != 154))
        return;
    runtime_redstone_update_comparator_output_level(
        r, inventory->wx, inventory->wy, inventory->wz);
}
